<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Color Tool · palette, converter, harmony</title>
  <!-- SEO friendly meta -->
  <meta name="description" content="Free all-in-one Color Tool: pick, convert, generate harmony, and adjust color easily. Modern, fast, and no API key required." />
  <link rel="canonical" href="https://colortool.example.com" />
  <!-- Preconnect for performance -->
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <!-- Google Font (clean & modern) -->
  <link href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&display=swap" rel="stylesheet" />
  <style>
    /* reset & base */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: #f7f9fc;
      color: #1e293b;
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 1.5rem;
      line-height: 1.5;
    }

    .app-card {
      max-width: 1200px;
      width: 100%;
      background: rgba(255, 255, 255, 0.75);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-radius: 2.5rem;
      box-shadow: 0 20px 40px -12px rgba(0, 20, 30, 0.25), 0 4px 18px rgba(0,0,0,0.05);
      padding: 2rem 2rem 2.5rem;
      transition: all 0.2s ease;
      border: 1px solid rgba(255,255,255,0.6);
    }

    /* header & info */
    .tool-header {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 2rem;
    }

    .tool-header h1 {
      font-weight: 700;
      font-size: 2.2rem;
      letter-spacing: -0.02em;
      background: linear-gradient(135deg, #2563eb, #7c3aed);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .tool-header h1 span {
      background: rgba(37, 99, 235, 0.08);
      padding: 0.2rem 0.9rem;
      border-radius: 40px;
      font-size: 0.9rem;
      font-weight: 500;
      color: #2563eb;
      background-clip: unset;
      -webkit-background-clip: unset;
      color: #2563eb;
      background: #e6f0ff;
    }

    .usage-badge {
      background: #eef2ff;
      padding: 0.6rem 1.4rem;
      border-radius: 60px;
      font-size: 0.9rem;
      font-weight: 500;
      color: #1e293b;
      display: flex;
      align-items: center;
      gap: 0.4rem;
      box-shadow: inset 0 1px 2px rgba(0,0,0,0.02);
    }

    .usage-badge i {
      font-size: 1.2rem;
    }

    .info-grid {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem 2rem;
      background: #f8fafc;
      padding: 0.9rem 1.8rem;
      border-radius: 60px;
      margin-bottom: 2.2rem;
      justify-content: center;
      border: 1px solid #e9edf2;
      font-size: 0.95rem;
    }

    .info-grid p {
      display: flex;
      align-items: center;
      gap: 0.3rem;
    }

    .info-grid strong {
      font-weight: 600;
      color: #0f172a;
    }

    /* main tool grid */
    .tool-grid {
      display: grid;
      grid-template-columns: 1fr 1.1fr;
      gap: 2rem;
    }

    @media (max-width: 820px) {
      .tool-grid {
        grid-template-columns: 1fr;
        gap: 2.2rem;
      }
      .app-card {
        padding: 1.5rem;
      }
      .tool-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
      }
      .usage-badge {
        align-self: flex-start;
      }
    }

    /* left panel: color picker + display */
    .picker-section {
      background: white;
      border-radius: 1.8rem;
      padding: 1.8rem 1.8rem 2rem;
      box-shadow: 0 8px 20px -8px rgba(0,0,0,0.06);
      border: 1px solid #f1f4f9;
    }

    .color-preview {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1.2rem;
    }

    .color-swatch {
      width: 100%;
      height: 160px;
      border-radius: 2rem;
      background: #2563eb;
      box-shadow: 0 8px 24px rgba(37, 99, 235, 0.2);
      transition: background 0.15s ease, box-shadow 0.2s;
    }

    .color-values {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.8rem 1.5rem;
      width: 100%;
      background: #f8fafc;
      padding: 0.8rem 1rem;
      border-radius: 60px;
      font-size: 0.9rem;
      font-weight: 500;
      border: 1px solid #eef2f6;
    }

    .color-values span {
      background: white;
      padding: 0.2rem 0.9rem;
      border-radius: 30px;
      box-shadow: 0 1px 4px rgba(0,0,0,0.02);
      font-family: 'Inter', monospace;
    }

    .input-group {
      display: flex;
      flex-direction: column;
      gap: 1rem;
      width: 100%;
      margin-top: 0.2rem;
    }

    .input-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.8rem;
      justify-content: space-between;
    }

    .input-row label {
      font-weight: 500;
      font-size: 0.9rem;
      color: #334155;
      min-width: 60px;
    }

    .input-row input[type="color"] {
      width: 60px;
      height: 60px;
      border: 2px solid #e2e8f0;
      border-radius: 40px;
      padding: 2px;
      background: white;
      cursor: pointer;
      transition: border 0.15s;
    }

    .input-row input[type="color"]:hover {
      border-color: #2563eb;
    }

    .input-row input[type="text"] {
      flex: 1;
      min-width: 140px;
      padding: 0.7rem 1.2rem;
      border: 1.5px solid #e2e8f0;
      border-radius: 60px;
      font-size: 0.95rem;
      font-weight: 500;
      background: white;
      transition: 0.2s;
      font-family: 'Inter', monospace;
    }

    .input-row input[type="text"]:focus {
      outline: none;
      border-color: #2563eb;
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    }

    .input-row input[type="range"] {
      flex: 2;
      min-width: 120px;
      accent-color: #2563eb;
      height: 6px;
      border-radius: 10px;
      background: #dbe1e9;
    }

    .input-row input[type="range"]::-webkit-slider-thumb {
      -webkit-appearance: none;
      appearance: none;
      width: 18px;
      height: 18px;
      border-radius: 50%;
      background: #2563eb;
      cursor: pointer;
      border: 2px solid white;
      box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    }

    .btn-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.7rem;
      margin-top: 0.5rem;
    }

    .btn {
      background: white;
      border: 1.5px solid #e2e8f0;
      padding: 0.6rem 1.4rem;
      border-radius: 60px;
      font-weight: 600;
      font-size: 0.85rem;
      color: #1e293b;
      cursor: pointer;
      transition: 0.15s;
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      flex: 1 0 auto;
      justify-content: center;
      background: #f8fafc;
    }

    .btn-primary {
      background: #2563eb;
      border-color: #2563eb;
      color: white;
      box-shadow: 0 4px 10px -4px rgba(37, 99, 235, 0.3);
    }

    .btn-primary:hover {
      background: #1d4ed8;
      border-color: #1d4ed8;
      transform: scale(0.97);
    }

    .btn-outline {
      background: transparent;
      border-color: #d0d8e3;
    }

    .btn-outline:hover {
      background: #f1f5f9;
      border-color: #b0c0d0;
    }

    /* right panel: harmonies & conversions */
    .harmony-section {
      background: white;
      border-radius: 1.8rem;
      padding: 1.8rem;
      border: 1px solid #f1f4f9;
      box-shadow: 0 8px 20px -8px rgba(0,0,0,0.04);
      display: flex;
      flex-direction: column;
      gap: 1.8rem;
    }

    .harmony-block h3 {
      font-weight: 600;
      font-size: 1.1rem;
      margin-bottom: 0.9rem;
      color: #0f172a;
      letter-spacing: -0.01em;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .harmony-swatches {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
    }

    .harmony-swatch {
      width: 54px;
      height: 54px;
      border-radius: 20px;
      background: #ccc;
      box-shadow: 0 2px 8px rgba(0,0,0,0.06);
      transition: 0.1s;
      border: 2px solid white;
      outline: 1px solid #e9edf2;
    }

    .conversion-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.8rem 1.2rem;
      background: #fafcff;
      padding: 0.8rem 1.2rem;
      border-radius: 1.8rem;
      border: 1px solid #edf2f7;
    }

    .conversion-item {
      display: flex;
      justify-content: space-between;
      font-size: 0.9rem;
      padding: 0.3rem 0;
      border-bottom: 1px dashed #e2e8f0;
    }

    .conversion-item:last-child,
    .conversion-item:nth-last-child(2) {
      border-bottom: none;
    }

    .conversion-item .label {
      color: #475569;
      font-weight: 500;
    }
    .conversion-item .value {
      font-weight: 600;
      font-family: 'Inter', monospace;
    }

    .copy-hint {
      font-size: 0.75rem;
      color: #64748b;
      margin-top: 0.3rem;
      display: flex;
      gap: 0.8rem;
      justify-content: flex-end;
    }

    /* footer */
    .tool-footer {
      margin-top: 2.5rem;
      font-size: 0.85rem;
      color: #64748b;
      border-top: 1px solid #e9edf2;
      padding-top: 1.8rem;
      text-align: center;
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 0.8rem 1.8rem;
    }

    .tool-footer strong {
      color: #1e293b;
      font-weight: 600;
    }

    /* utility */
    .text-muted {
      color: #64748b;
    }

    .gap-1 { gap: 0.4rem; }
  </style>
