<body>

<div class="card" role="main">
  <div class="tool-header">
    <h1>
      🎨 Color Shades
      <span>Generator</span>
    </h1>
    <div class="badge">
      <i>⚡</i> 100% free · no API
    </div>
  </div>

  <!-- input area -->
  <div class="input-section">
    <div class="color-picker-wrapper">
      <label for="baseColor">Base</label>
      <input type="color" id="baseColor" value="#6b3f8b">
      <div class="hex-input-group">
        <input type="text" id="hexInput" placeholder="#HEX" value="#6b3f8b" spellcheck="false">
        <button id="applyHexBtn">Apply</button>
      </div>
    </div>
  </div>

  <!-- slider for steps -->
  <div class="slider-section">
    <label for="shadeCount">🔢 Shades <span style="font-weight:400; margin-left:4px;">(lighter + darker)</span></label>
    <input type="range" id="shadeCount" min="2" max="8" value="5" step="1">
    <span class="slider-value" id="shadeCountDisplay">5</span>
  </div>

  <!-- shade grid -->
  <div id="shadeGridContainer" class="shade-grid"></div>

  <!-- info & howto -->
  <div class="info-box">
    <p>
      <i>✨</i> 
      <span>Lighter shades (top) · darker shades (bottom). Click any color to copy hex.</span>
    </p>
    <div class="howto">
      <span>⏵</span> pick color · adjust slider · instant
    </div>
  </div>
  <div class="footer-note">
    ⚡ fast · reliable · 100% uptime
  </div>
</div>

<script>
  (function() {
    "use strict";

    // DOM refs
    const baseColorPicker = document.getElementById('baseColor');
    const hexInput = document.getElementById('hexInput');
    const applyHexBtn = document.getElementById('applyHexBtn');
    const shadeCountSlider = document.getElementById('shadeCount');
    const shadeCountDisplay = document.getElementById('shadeCountDisplay');
    const shadeGrid = document.getElementById('shadeGridContainer');

    // helper: clamp & parse int
    const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

    // convert hex to RGB {r,g,b} (supports #RGB, #RRGGBB)
    function hexToRgb(hex) {
      let c = hex.trim();
      if (c.startsWith('#')) c = c.slice(1);
      if (c.length === 3) c = c.split('').map(ch => ch + ch).join('');
      if (c.length !== 6) return null;
      const r = parseInt(c.substring(0,2), 16);
      const g = parseInt(c.substring(2,4), 16);
      const b = parseInt(c.substring(4,6), 16);
      if (isNaN(r) || isNaN(g) || isNaN(b)) return null;
      return { r, g, b };
    }

    // RGB to hex string
    function rgbToHex(r, g, b) {
      const clampVal = (v) => clamp(Math.round(v), 0, 255);
      const rh = clampVal(r).toString(16).padStart(2, '0');
      const gh = clampVal(g).toString(16).padStart(2, '0');
      const bh = clampVal(b).toString(16).padStart(2, '0');
      return `#${rh}${gh}${bh}`.toUpperCase();
    }

    // generate shades: count = total shades (including base). 
    // returns array of objects: { hex, label, rgb }
    function generateShades(baseHex, totalCount) {
      if (totalCount < 2) totalCount = 2;
      const rgb = hexToRgb(baseHex);
      if (!rgb) return [];

      const { r, g, b } = rgb;
      const result = [];

      // we want (totalCount) shades: lighter (half) and darker (half), base in middle
      // if totalCount is odd, base is exactly in middle; if even, base is between two middle.
      const half = Math.floor(totalCount / 2);
      const lightCount = totalCount % 2 === 0 ? half : half;   // e.g total 5 -> half=2 light, 2 dark, base in middle
      const darkCount = totalCount % 2 === 0 ? half : half;    // same

      // lighter shades (index 0 .. lightCount-1) from 100% -> 0% (base)
      for (let i = 0; i < lightCount; i++) {
        const t = (i + 1) / (lightCount + 1);  // 0.1 .. 0.9
        // mix with white (255,255,255)
        const lr = r + (255 - r) * t;
        const lg = g + (255 - g) * t;
        const lb = b + (255 - b) * t;
        const hex = rgbToHex(lr, lg, lb);
        result.push({ hex, label: `L${i+1}`, rgb: { r: lr, g: lg, b: lb } });
      }

      // base color (placed after lighter)
      result.push({ hex: rgbToHex(r, g, b), label: 'BASE', rgb: { r, g, b } });

      // darker shades (index darkCount .. 1) from 0% -> 100% (base)
      for (let i = 0; i < darkCount; i++) {
        const t = (i + 1) / (darkCount + 1);
        const dr = r * (1 - t);
        const dg = g * (1 - t);
        const db = b * (1 - t);
        const hex = rgbToHex(dr, dg, db);
        result.push({ hex, label: `D${i+1}`, rgb: { r: dr, g: dg, b: db } });
      }

      return result;
    }

    // render grid
    function renderShades(baseHex, count) {
      const shades = generateShades(baseHex, count);
      if (!shades || shades.length === 0) {
        shadeGrid.innerHTML = `<div style="grid-column:1/-1; text-align:center; padding:2rem; color:#7a6190;">⚠️ Please enter a valid hex color</div>`;
        return;
      }

      let html = '';
      for (const s of shades) {
        const label = s.label;
        const hex = s.hex;
        html += `
          <div class="shade-item" data-hex="${hex}" role="button" tabindex="0" title="Click to copy hex">
            <div class="color-preview" style="background: ${hex};"></div>
            <div class="shade-label">${label}</div>
            <div class="shade-hex">${hex}</div>
          </div>
        `;
      }
      shadeGrid.innerHTML = html;

      // click to copy hex
      document.querySelectorAll('.shade-item').forEach(el => {
        const hexVal = el.dataset.hex;
        el.addEventListener('click', function(e) {
          e.stopPropagation();
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(hexVal).then(() => {
              // subtle feedback
              const prev = this.style.transition;
              this.style.transition = 'background 0.1s';
              this.style.background = 'rgba(107,63,139,0.08)';
              setTimeout(() => { this.style.background = ''; }, 120);
            }).catch(() => {});
          } else {
            // fallback
            const textArea = document.createElement('textarea');
            textArea.value = hexVal;
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand('copy');
            document.body.removeChild(textArea);
          }
        });
        // keyboard
        el.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            el.click();
          }
        });
      });
    }

    // update from color picker
    function updateFromPicker() {
      const hex = baseColorPicker.value;
      hexInput.value = hex.toUpperCase();
      const count = parseInt(shadeCountSlider.value, 10);
      renderShades(hex, count);
    }

    // update from hex input
    function updateFromHexInput() {
      let val = hexInput.value.trim();
      if (!val.startsWith('#')) val = '#' + val;
      if (/^#[0-9a-fA-F]{3}$|^#[0-9a-fA-F]{6}$/.test(val)) {
        baseColorPicker.value = val;
        const count = parseInt(shadeCountSlider.value, 10);
        renderShades(val, count);
      } else {
        // if invalid, we just show a gentle reminder (but keep old)
        hexInput.style.border = '1px solid #d4b8d9';
        setTimeout(() => hexInput.style.border = '', 600);
        // try to fix: if it's a valid 6-char hex without #
        const cleaned = val.replace('#', '');
        if (/^[0-9a-fA-F]{6}$/.test(cleaned)) {
          const fixed = '#' + cleaned.toUpperCase();
          baseColorPicker.value = fixed;
          hexInput.value = fixed;
          const count = parseInt(shadeCountSlider.value, 10);
          renderShades(fixed, count);
        }
      }
    }

    // slider display + update
    function handleSliderChange() {
      const val = shadeCountSlider.value;
      shadeCountDisplay.textContent = val;
      const hex = baseColorPicker.value;
      renderShades(hex, parseInt(val, 10));
    }

    // --- init ---
    function init() {
      // set initial color
      const initialHex = '#6B3F8B';
      baseColorPicker.value = initialHex;
      hexInput.value = initialHex.toUpperCase();
      shadeCountSlider.value = '5';
      shadeCountDisplay.textContent = '5';
      renderShades(initialHex, 5);

      // event listeners
      baseColorPicker.addEventListener('input', updateFromPicker);
      applyHexBtn.addEventListener('click', updateFromHexInput);
      hexInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          updateFromHexInput();
        }
      });
      shadeCountSlider.addEventListener('input', handleSliderChange);

      // extra: if user blurs hex input, apply
      hexInput.addEventListener('blur', updateFromHexInput);
    }

    init();
  })();
</script>

<!-- simple inline note for SEO -->
</body>
</html>
