    }

    .info-section .info-grid {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem 1.8rem;
      background: #f2f8ff;
      padding: 1rem 1.4rem;
      border-radius: 28px;
      color: #204078;
      font-size: 0.9rem;
    }

    .info-section .info-grid span {
      background: #ffffffb0;
      padding: 0.2rem 0.8rem;
      border-radius: 40px;
      display: inline-flex;
