<body>
  <div class="card" role="main">
    <div class="tool-header">
      <h1>⏱️ Rate<span style="font-weight: 400;">Builder</span></h1>
      <span class="badge">freelance · pro</span>
    </div>
    <div class="subhead">
      <strong>Your ideal hourly rate</strong> — based on annual salary, overhead, and billable hours. Adjust the numbers, get instant insight.
    </div>

    <!-- calculator inputs -->
    <form id="rateForm" class="rate-grid" autocomplete="off">
      <div class="input-group">
        <label for="salary">Desired salary <i>$/year</i></label>
        <input type="number" id="salary" placeholder="e.g. 75000" value="75000" step="1000" min="0">
        <span class="hint">gross annual</span>
      </div>
      <div class="input-group">
        <label for="overhead">Overhead <i>%</i></label>
        <input type="number" id="overhead" placeholder="e.g. 25" value="25" step="1" min="0" max="200">
        <span class="hint">taxes, insurance, etc.</span>
      </div>
      <div class="input-group">
        <label for="billable">Billable hours <i>/year</i></label>
        <input type="number" id="billable" placeholder="e.g. 1600" value="1600" step="50" min="1">
        <span class="hint">paid client work</span>
      </div>
      <div class="input-group" style="grid-column: span 1;">
        <label for="profit">Profit margin <i>%</i></label>
        <input type="number" id="profit" placeholder="e.g. 10" value="10" step="1" min="0" max="100">
        <span class="hint">optional buffer</span>
      </div>
    </form>

    <!-- result + actions -->
    <div class="action-area">
      <div class="result-box">
        <span class="label">💰 hourly rate</span>
        <span class="currency">$</span>
        <span class="value" id="rateDisplay">58.59</span>
      </div>
      <div style="display: flex; gap: 0.6rem; flex-wrap: wrap;">
        <button class="btn" id="calcBtn">↻ calculate</button>
        <button class="btn btn-outline" id="resetBtn">reset</button>
      </div>
    </div>

    <!-- info & instructions -->
    <div class="info-section">
      <h3>📋 how to use</h3>
      <div class="info-grid">
        <span>① <strong>salary</strong> + overhead</span>
        <span>② <strong>billable</strong> hours</span>
        <span>③ profit <strong>margin</strong></span>
        <span class="highlight">⚡ rate updates live</span>
      </div>
      <div style="margin-top: 0.8rem; font-size: 0.95rem; line-height: 1.5; color: #1f3760; background: #f7fbff; padding: 0.4rem 1.2rem; border-radius: 40px;">
        <span style="background: #d1e2fc; padding: 0.1rem 0.7rem; border-radius: 30px; font-weight: 500;">formula</span> 
        <span style="font-family: monospace; background: #eaf1fc; padding: 0.1rem 0.6rem; border-radius: 20px;">(salary × (1 + overhead/100) × (1 + profit/100)) / billable</span>
      </div>
      <div class="footnote">
        <span><span style="background: #c7dcfd; padding: 0.1rem 0.5rem; border-radius: 20px;">✓</span> no API · 100% client-side</span>
        <span><i>💡</i> adjust numbers, rate recalculates instantly</span>
      </div>
    </div>
  </div>

  <script>
    (function() {
      "use strict";

      // DOM refs
      const salaryInput = document.getElementById('salary');
      const overheadInput = document.getElementById('overhead');
      const billableInput = document.getElementById('billable');
      const profitInput = document.getElementById('profit');
      const rateDisplay = document.getElementById('rateDisplay');
      const calcBtn = document.getElementById('calcBtn');
      const resetBtn = document.getElementById('resetBtn');

      // Default values (matching placeholders)
      const DEFAULTS = {
        salary: 75000,
        overhead: 25,
        billable: 1600,
        profit: 10
      };

      // Helper: parse float or fallback
      function getVal(input, fallback) {
        const raw = input.value.trim().replace(/,/g, '');
        const num = parseFloat(raw);
        return isNaN(num) || num < 0 ? fallback : num;
      }

      // Core calculation
      function calculateRate() {
        const salary = getVal(salaryInput, DEFAULTS.salary);
        const overhead = getVal(overheadInput, DEFAULTS.overhead);
        const billable = getVal(billableInput, DEFAULTS.billable);
        const profit = getVal(profitInput, DEFAULTS.profit);

        // avoid division by zero or negative billable
        if (billable <= 0) {
          rateDisplay.textContent = '∞';
          return;
        }

        // overhead factor: e.g., 25% -> 1.25
        const overheadFactor = 1 + (overhead / 100);
        // profit factor: e.g., 10% -> 1.10
        const profitFactor = 1 + (profit / 100);
        // gross adjusted salary
        const adjustedSalary = salary * overheadFactor * profitFactor;
        const rate = adjustedSalary / billable;

        // format: 2 decimals, no trailing zeros if whole number
        if (rate > 0 && isFinite(rate)) {
          rateDisplay.textContent = rate.toFixed(2);
        } else {
          rateDisplay.textContent = '0.00';
        }
      }

      // Reset to defaults
      function resetToDefaults() {
        salaryInput.value = DEFAULTS.salary;
        overheadInput.value = DEFAULTS.overhead;
        billableInput.value = DEFAULTS.billable;
        profitInput.value = DEFAULTS.profit;
        calculateRate();
      }

      // Event listeners for "real-time" (input + change)
      function attachRealtime() {
        const inputs = [salaryInput, overheadInput, billableInput, profitInput];
        inputs.forEach(inp => {
          inp.addEventListener('input', calculateRate);
          inp.addEventListener('change', calculateRate);
        });
      }

      // button events
      calcBtn.addEventListener('click', (e) => {
        e.preventDefault();
        calculateRate();
        // subtle feedback (optional)
        calcBtn.style.transform = 'scale(0.97)';
        setTimeout(() => { calcBtn.style.transform = ''; }, 120);
      });

      resetBtn.addEventListener('click', (e) => {
        e.preventDefault();
        resetToDefaults();
        resetBtn.style.transform = 'scale(0.95)';
        setTimeout(() => { resetBtn.style.transform = ''; }, 120);
      });

      // extra: handle empty or invalid inputs gracefully
      function sanitizeInputs() {
        [salaryInput, overheadInput, billableInput, profitInput].forEach(inp => {
          inp.addEventListener('blur', function() {
            if (this.value.trim() === '') {
              // if empty, set to default (per field)
              if (this === salaryInput) this.value = DEFAULTS.salary;
              else if (this === overheadInput) this.value = DEFAULTS.overhead;
              else if (this === billableInput) this.value = DEFAULTS.billable;
              else if (this === profitInput) this.value = DEFAULTS.profit;
              calculateRate();
            }
            // if negative, clamp to 0 (or min)
            let val = parseFloat(this.value);
            if (!isNaN(val) && val < 0) {
              this.value = 0;
              calculateRate();
            }
            if (this === billableInput && !isNaN(val) && val <= 0) {
              // keep as is, but rate will show ∞ (handled)
            }
          });
        });
      }

      // Init
      function init() {
        // set default values
        resetToDefaults();
        attachRealtime();
        sanitizeInputs();
        // ensure rate shows on load (already called in resetToDefaults)
        // but if any default is off, recalc
        calculateRate();
      }

      init();

      // Extra: add a small "tooltip" effect: rate updates on any change
      // also detect if user pastes a value
      document.addEventListener('paste', function(e) {
        // If the paste target is one of our inputs, schedule a recalculation
        const target = e.target;
        if (target && (target === salaryInput || target === overheadInput || 
                       target === billableInput || target === profitInput)) {
          setTimeout(calculateRate, 20);
        }
      });

      // handle manual edge: if billable is 0, show '∞' but we display 0.00
      // override to show a friendly message? but we keep as 0.00
      // we already guard division by zero

      console.log('💰 Hourly Rate Calculator ready — no API, always on.');
    })();
  </script>
</body>
</html>
