<div class="card" role="main">
<p><!-- header --></p>
<div class="header">
<p> </p>
<h1>You Tube Title Forge</h1>
</div>
<div class="subhead"><i class="fas fa-bolt" style="margin-right: 6px; color: #3b4fef;"></i> 5 fresh titles · 8 styles · zero API</div>
<p><!-- brief info & usage --></p>
<div class="info-box">
<p> </p>
<div class="info-text"><strong>How to use:</strong> Type your video topic, pick a style, click Generate. Get 5 titles instantly. Copy any title with the <i class="far fa-copy" style="margin: 0 2px;"></i> icon. Works offline, always free.</div>
</div>
<p><!-- input area --></p>
<div class="input-group">
<div class="input-wrapper"><i class="fas fa-pen"></i> <input id="topicInput" type="text" value="coding in the rain" placeholder="e.g. 'indie game dev vlog'" /></div>
<div class="style-select"><i class="fas fa-sliders-h"></i><select id="styleSelect">
<option value="clickbait">🔥 Clickbait</option>
<option selected="selected" value="howto">📘 How-to</option>
<option value="list">📋 List / Top</option>
<option value="story">📖 Storytelling</option>
<option value="question">❓ Question</option>
<option value="epic">⚡ Epic / Cinematic</option>
<option value="funny">😂 Funny / Meme</option>
<option value="minimal">✨ Minimal / Clean</option>
</select></div>
<p><button id="generateBtn" class="generate-btn"> <i class="fas fa-arrow-right"></i> Generate </button></p>
