    }

    .toast.show {
      opacity: 1;
      transform: translateX(-50%) translateY(0px);
    }
  </style>
</head>
<body>
  <div class="card" role="main">
    <h1>
      <i class="fas fa-brain"></i> Memorable
    </h1>
    <div class="subhead">
      <i class="fas fa-shield-alt" style="margin-right: 10px; color: #6a549a;"></i> 
      Strong · Human-friendly · Client-side
    </div>

    <!-- password output -->
    <div class="generated-box">
      <input type="text" id="passwordDisplay" placeholder="✨ click generate" readonly aria-label="Generated password">
      <button class="copy-btn" id="copyBtn" aria-label="Copy password" title="Copy to clipboard">
        <i class="fas fa-copy"></i>
      </button>
    </div>

    <!-- controls -->
    <div class="control-grid">
      <div class="control-item">
        <label for="lengthSlider"><i class="fas fa-ruler"></i> Length</label>
        <input type="range" id="lengthSlider" min="4" max="20" value="8" step="1">
        <span class="range-value" id="lengthDisplay">8</span>
      </div>
      <div class="control-item">
        <label for="separatorSelect"><i class="fas fa-link"></i> Separator</label>
        <select id="separatorSelect" class="separator-select">
          <option value="-"> —  hyphen ( - )</option>
          <option value="."> ·  dot ( . )</option>
          <option value="_"> _  underscore ( _ )</option>
          <option value=" "> space (  )</option>
          <option value=""> none (joined)</option>
        </select>
      </div>
    </div>

    <!-- checkboxes & extra -->
    <div class="checkbox-group">
      <label class="checkbox-item">
        <input type="checkbox" id="includeNumbers" checked> <i class="fas fa-hashtag"></i> Numbers
      </label>
      <label class="checkbox-item">
        <input type="checkbox" id="includeSymbols"> <i class="fas fa-asterisk"></i> Symbols
      </label>
    </div>

    <!-- action buttons -->
    <div class="actions">
      <button class="btn btn-primary" id="generateBtn"><i class="fas fa-sync-alt"></i> Generate</button>
      <button class="btn btn-secondary" id="regenerateBtn"><i class="fas fa-dice"></i> New</button>
    </div>

    <!-- info & how-to -->
    <div class="info-section">
      <h3><i class="fas fa-lightbulb" style="color:#7a63b0;"></i> How it works</h3>
      <p>Combines common words with a separator, optional numbers and symbols. 
      <span style="background: #e6def5; padding: 0.1rem 0.7rem; border-radius: 40px;">e.g. <strong>tiger•river•9!</strong></span>
      </p>
      <ul>
        <li><i class="fas fa-check-circle"></i> 3 random words</li>
        <li><i class="fas fa-check-circle"></i> Separator of choice</li>
        <li><i class="fas fa-check-circle"></i> Optionally digits & symbols</li>
        <li><i class="fas fa-check-circle"></i> 100% local, no API</li>
      </ul>
    </div>
    <div class="footer-note">
      <i class="fas fa-lock" style="margin-right: 6px;"></i> private · zero storage
    </div>
  </div>

  <!-- toast -->
  <div id="toast" class="toast">✓ Copied to clipboard</div>

  <script>
    (function() {
      "use strict";

      // ---- word bank (memorable, common) ----
      const WORDS = [
        "tiger", "river", "cloud", "flame", "stone", "brave", "crisp", "dusk", "eagle", "fable",
        "grace", "haze", "ivory", "jade", "kind", "lunar", "mirth", "noble", "oasis", "pulse",
        "quiet", "roam", "solar", "tide", "umbra", "vivid", "wisp", "zen", "bloom", "coral",
        "dove", "ember", "frost", "gale", "heath", "iris", "jewel", "kite", "lush", "moon",
        "nectar", "oak", "pearl", "quill", "rain", "sage", "thorn", "ulna", "vale", "willow",
        "xenon", "yarn", "zephyr", "ark", "briar", "crane", "drift", "echo", "fawn", "glimmer"
      ];

      // ---- DOM refs ----
      const passwordDisplay = document.getElementById('passwordDisplay');
      const lengthSlider = document.getElementById('lengthSlider');
      const lengthDisplay = document.getElementById('lengthDisplay');
      const separatorSelect = document.getElementById('separatorSelect');
      const includeNumbers = document.getElementById('includeNumbers');
      const includeSymbols = document.getElementById('includeSymbols');
      const generateBtn = document.getElementById('generateBtn');
      const regenerateBtn = document.getElementById('regenerateBtn');
      const copyBtn = document.getElementById('copyBtn');
      const toast = document.getElementById('toast');

      let currentPassword = '';

      // ---- helpers ----
      function getRandomItem(arr) {
        return arr[Math.floor(Math.random() * arr.length)];
      }

      // pick 3 distinct words (if possible)
      function pickThreeWords() {
        const shuffled = [...WORDS];
        for (let i = shuffled.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
        }
        return shuffled.slice(0, 3);
      }

      // generate memorable password
      function generatePassword() {
        const length = parseInt(lengthSlider.value, 10);
        const sep = separatorSelect.value;
        const useNumbers = includeNumbers.checked;
        const useSymbols = includeSymbols.checked;

        // 3 words
        let words = pickThreeWords();
        // ensure we have 3 words (if bank smaller, but it's fine)
        while (words.length < 3) words.push(getRandomItem(WORDS));

        // optional number & symbol
        let numberPart = '';
        let symbolPart = '';
        if (useNumbers) {
          numberPart = String(Math.floor(Math.random() * 10)); // 0-9
        }
        if (useSymbols) {
          const symbols = ['!', '@', '#', '$', '%', '&', '?', '*'];
          symbolPart = getRandomItem(symbols);
        }

        // build password: word + sep + word + sep + word + (number + symbol)
        let base = words.join(sep);
        let suffix = numberPart + symbolPart;
        // if both number and symbol are present, maybe we want to keep them together
        // if only one, it's fine. If none, suffix empty.
        let result = base + suffix;

        // now adjust length: if result longer than desired, truncate from end (but keep structure)
        if (result.length > length) {
          // we truncate from the end (remove suffix chars first, then words)
          while (result.length > length && result.length > 0) {
            result = result.slice(0, -1);
          }
        } 
        // if result shorter than desired, pad with random digits/letters? 
        // but we want 'memorable', so we pad with random lowercase (or digits) if requested.
        // but we keep it simple: if too short, we add random chars from words
        while (result.length < length) {
          // append random char from a-z or digits if allowed
          const pool = 'abcdefghijklmnopqrstuvwxyz' + (useNumbers ? '0123456789' : '');
          if (pool.length > 0) {
            result += pool.charAt(Math.floor(Math.random() * pool.length));
          } else {
            result += 'x'; // fallback
          }
        }

        // ensure we don't exceed desired length (just in case)
        if (result.length > length) {
          result = result.slice(0, length);
        }

        return result;
      }

      function updatePassword() {
        currentPassword = generatePassword();
        passwordDisplay.value = currentPassword;
      }

      // ---- copy ----
      function copyPassword() {
        if (!currentPassword) {
          updatePassword();
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(currentPassword).then(() => {
            showToast('✓ Copied!');
          }).catch(() => {
            fallbackCopy();
          });
        } else {
          fallbackCopy();
        }
      }

      function fallbackCopy() {
        passwordDisplay.select();
        passwordDisplay.setSelectionRange(0, 99999);
        document.execCommand('copy');
        showToast('✓ Copied!');
        passwordDisplay.blur();
      }

      let toastTimeout;

      function showToast(msg) {
        toast.textContent = msg || '✓ Copied to clipboard';
        toast.classList.add('show');
        clearTimeout(toastTimeout);
        toastTimeout = setTimeout(() => {
          toast.classList.remove('show');
        }, 2200);
      }

      // ---- UI events ----
      function handleGenerate() {
        updatePassword();
        // show toast briefly? 
      }

      // length display
      lengthSlider.addEventListener('input', function() {
        lengthDisplay.textContent = this.value;
      });

      generateBtn.addEventListener('click', handleGenerate);
      regenerateBtn.addEventListener('click', handleGenerate);
      copyBtn.addEventListener('click', copyPassword);

      // also generate on checkbox/select change? We'll let user click Generate.
      // but we can also auto-update? We'll keep it manual to avoid surprises.
      // double-click on password box also copies?
      passwordDisplay.addEventListener('dblclick', copyPassword);

      // initial generation
      updatePassword();

      // optionally regenerate on any change of controls? We'll not auto to keep user in control.
      // but we can add a subtle hint: pressing Enter on any input triggers generate.
      document.querySelectorAll('input, select').forEach(el => {
        el.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            handleGenerate();
          }
        });
      });

      // extra: accessibility — generate on ctrl+enter
      document.addEventListener('keydown', (e) => {
        if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
          e.preventDefault();
          handleGenerate();
        }
      });

    })();
  </script>
</body>
</html>
