  </style>
</head>
<body>
<div class="card">
  <!-- header -->
  <div class="subhead">
    <h1>📝 Word Counter</h1>
    <span class="badge-tag">⚡ 100% client-side</span>
  </div>

  <!-- stats -->
  <div class="stats-grid" id="statsGrid">
    <div class="stat-item"><span class="stat-number" id="wordCount">0</span><span class="stat-label">Words</span></div>
    <div class="stat-item"><span class="stat-number" id="charCount">0</span><span class="stat-label">Characters</span></div>
    <div class="stat-item"><span class="stat-number" id="sentenceCount">0</span><span class="stat-label">Sentences</span></div>
    <div class="stat-item"><span class="stat-number" id="paraCount">0</span><span class="stat-label">Paragraphs</span></div>
    <div class="stat-item"><span class="stat-number" id="readingTime">0</span><span class="stat-label">Read time (min)</span></div>
  </div>

  <!-- text input -->
  <div class="textarea-wrapper">
    <textarea id="textInput" placeholder="Type or paste your text here …" aria-label="Text to analyze"></textarea>
  </div>

  <!-- actions -->
  <div class="action-row">
    <div class="btn-group">
      <button class="btn" id="clearBtn" aria-label="Clear text">✕ Clear</button>
      <button class="btn" id="sampleBtn" aria-label="Load sample text">📄 Sample</button>
    </div>
    <button class="btn btn-primary" id="copyBtn">📋 Copy stats</button>
  </div>

  <!-- info & how-to -->
  <div class="info-box">
    <span class="info-text">
      <strong>✨ How to use</strong> — start typing or paste your content. 
      Words, characters, sentences, paragraphs and reading time update instantly.
    </span>
    <span class="info-text" style="font-size:0.8rem;">
      <span class="highlight">⚙️</span> no API, no delays
    </span>
  </div>
  <div class="footer-meta">
    Word Counter · free &amp; privacy-first — all processing is done in your browser.
  </div>
</div>

<script>
  (function() {
    "use strict";

    // DOM refs
    const textarea = document.getElementById('textInput');
    const wordSpan = document.getElementById('wordCount');
    const charSpan = document.getElementById('charCount');
    const sentenceSpan = document.getElementById('sentenceCount');
    const paraSpan = document.getElementById('paraCount');
    const readingSpan = document.getElementById('readingTime');

    const clearBtn = document.getElementById('clearBtn');
    const sampleBtn = document.getElementById('sampleBtn');
    const copyBtn = document.getElementById('copyBtn');

    // ----- core counter function (fast, reliable) -----
    function countMetrics(text) {
      // handle empty / whitespace
      const trimmed = text.trim();
      if (!trimmed) {
        return { words: 0, chars: 0, sentences: 0, paragraphs: 0, readingTime: 0 };
      }

      // 1) characters (with spaces)
      const chars = text.length;

      // 2) words: split on whitespace, filter empty
      const wordsArray = trimmed.split(/\s+/).filter(w => w.length > 0);
      const words = wordsArray.length;

      // 3) sentences: count . ! ?  (but not abbreviations, simple robust)
      // using regex that splits on sentence endings, also handles multiple punctuation
      const sentenceMatches = text.match(/[.!?]+(?!\w)/g);
      let sentences = 0;
      if (sentenceMatches) {
        // count occurrence of sentence-ending punctuation, but at least 1 if text non-empty
        sentences = sentenceMatches.length;
      }
      // if no punctuation but has text, consider as 1 sentence
      if (sentences === 0 && trimmed.length > 0) sentences = 1;

      // 4) paragraphs: split by newline (two or more newlines define paragraph break)
      // but also treat single newline as paragraph? we use double newline for conventional.
      let paragraphs = 0;
      // split by \n\n and filter empty, but also handle single newline if content
      const paraSplit = text.split(/\n\s*\n/).filter(p => p.trim().length > 0);
      if (paraSplit.length > 0) {
        paragraphs = paraSplit.length;
      } else {
        // if no double newline, count single newline or if text has lines
        const lines = text.split('\n').filter(line => line.trim().length > 0);
        paragraphs = lines.length > 0 ? lines.length : (trimmed.length > 0 ? 1 : 0);
      }
      // edge: if paragraphs still 0 but text non-empty -> 1
      if (paragraphs === 0 && trimmed.length > 0) paragraphs = 1;

      // 5) reading time: avg 200 words per minute (rounded, min 1 if words > 0)
      let readingTime = 0;
      if (words > 0) {
        readingTime = Math.max(1, Math.round(words / 200));
        // if less than 1 but words > 0, set to 1 (fits "min")
        if (readingTime < 1) readingTime = 1;
      }

      return { words, chars, sentences, paragraphs, readingTime };
    }

    // ----- update UI -----
    function updateStats() {
      const text = textarea.value;
      const stats = countMetrics(text);

      wordSpan.textContent = stats.words;
      charSpan.textContent = stats.chars;
      sentenceSpan.textContent = stats.sentences;
      paraSpan.textContent = stats.paragraphs;
      readingSpan.textContent = stats.readingTime;
    }

    // ----- event listeners -----
    textarea.addEventListener('input', updateStats);

    // clear
    clearBtn.addEventListener('click', function() {
      textarea.value = '';
      updateStats();
      textarea.focus();
    });

    // sample text (rich, varied)
    sampleBtn.addEventListener('click', function() {
      const sample = `The quick brown fox jumps over the lazy dog. This sentence contains several words. And here is another one! 

  Did you know? A paragraph is defined by a line break. This tool counts every detail: words, characters, sentences, paragraphs, and even reading time.

  It's perfect for writers, students, and editors. Clean, modern, and blazing fast. No ads, no tracking, just pure utility. 

  Enjoy using this word counter! 🚀`;
      textarea.value = sample;
      updateStats();
      textarea.focus();
    });

    // copy stats as formatted text
    copyBtn.addEventListener('click', function() {
      const words = wordSpan.textContent;
      const chars = charSpan.textContent;
      const sentences = sentenceSpan.textContent;
      const paras = paraSpan.textContent;
      const reading = readingSpan.textContent;

      const statsText = `📊 Word Counter stats:
  • Words: ${words}
  • Characters: ${chars}
  • Sentences: ${sentences}
  • Paragraphs: ${paras}
  • Reading time: ${reading} min`;

      navigator.clipboard.writeText(statsText).then(() => {
        // visual feedback (brief)
        const original = copyBtn.textContent;
        copyBtn.textContent = '✅ Copied!';
        setTimeout(() => { copyBtn.textContent = original; }, 1500);
      }).catch(() => {
        // fallback (select & copy)
        alert('Copy: select the stats manually.');
      });
    });

    // initialize with placeholder (empty) — but we can set a small example?
    // for better UX, we put a tiny example? leave empty but with placeholder.
    // we set sample text on first focus? optional, but we'll keep empty.
    // but we want to show something maybe: we set default sample (light)
    // Because tool should be functional right away, we add sample on load.
    window.addEventListener('load', function() {
      // set a mild sample so user sees the counter in action
      const defaultDemo = `Welcome! Start typing or paste your content. The counter updates in real-time.`;
      textarea.value = defaultDemo;
      updateStats();
    });

    // additional: ensure stats update on any external change
    // also on paste, cut, etc. input event covers all.

    // Edge: if user clears and we want zero state, fine.

    // make sure resize etc no effect.

    console.log('Word Counter ready.');
  })();
</script>
</body>
</html>
