 chars: '𝘼𝘽𝘾𝘿𝙀𝙁𝙂𝙃𝙄𝙅𝙆𝙇𝙈𝙉𝙊𝙋𝙌𝙍𝙎𝙏𝙐𝙑𝙒𝙓𝙔𝙕',
 lower: '𝙖𝙗𝙘𝙙𝙚𝙛𝙜𝙝𝙞𝙟𝙠𝙡𝙢𝙣𝙤𝙥𝙦𝙧𝙨𝙩𝙪𝙫𝙬𝙭𝙮𝙯',
 desc: '𝙎𝘽𝙄'
 },
 'Gothic / Fraktur': {
 chars: '𝔄𝔅ℭ𝔇𝔈𝔉𝔊ℌℑ𝔍𝔎𝔏𝔐𝔑𝔒𝔓𝔔ℜ𝔖𝔗𝔘𝔙𝔚𝔛𝔜ℨ',
 lower: '𝔞𝔟𝔠𝔡𝔢𝔣𝔤𝔥𝔦𝔧𝔨𝔩𝔪𝔫𝔬𝔭𝔮𝔯𝔰𝔱𝔲𝔳𝔴𝔵𝔶𝔷',
 desc: '𝕲𝖔𝖙𝖍'
 },
 'Bold Fraktur': {
 chars: '𝕬𝕭𝕮𝕯𝕰𝕱𝕲𝕳𝕴𝕵𝕶𝕷𝕸𝕹𝕺𝕻𝕼𝕽𝕾𝕿𝖀𝖁𝖂𝖃𝖄𝖅',
 lower: '𝖆𝖇𝖈𝖉𝖊𝖋𝖌𝖍𝖎𝖏𝖐𝖑𝖒𝖓𝖔𝖕𝖖𝖗𝖘𝖙𝖚𝖛𝖜𝖝𝖞𝖟',
 desc: '𝗕𝗙'
 },
 'Circled': {
 chars: 'ⒶⒷⒸⒹⒺⒻⒼⒽⒾⒿⓀⓁⓂⓃⓄⓅⓆⓇⓈⓉⓊⓋⓌⓍⓎⓏ',
 lower: 'ⓐⓑⓒⓓⓔⓕⓖⓗⓘⓙⓚⓛⓜⓝⓞⓟⓠⓡⓢⓣⓤⓥⓦⓧⓨⓩ',
 desc: 'Ⓒⓘⓡⓒ'
 },
 'Parenthesis': {
 chars: '⒜⒝⒞⒟⒠⒡⒢⒣⒤⒥⒦⒧⒨⒩⒪⒫⒬⒭⒮⒯⒰⒱⒲⒳⒴⒵',
 lower: '⒜⒝⒞⒟⒠⒡⒢⒣⒤⒥⒦⒧⒨⒩⒪⒫⒬⒭⒮⒯⒰⒱⒲⒳⒴⒵',
 desc: '(🅟)'
 },
 'Small caps': {
 chars: 'ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢ',
 lower: 'ᴀʙᴄᴅᴇꜰɢʜɪᴊᴋʟᴍɴᴏᴘǫʀꜱᴛᴜᴠᴡxʏᴢ',
 desc: 'sᴍᴀʟʟ'
 }
 };

 // style list for UI (order)
 const styleNames = [
 'Bold', 'Italic', 'Bold Italic', 'Script', 'Bold Script', 
 'Monospace', 'Double Struck', 'Sans Serif', 'Sans Bold', 
 'Sans Italic', 'Sans Bold Italic', 'Gothic / Fraktur', 
 'Bold Fraktur', 'Circled', 'Parenthesis', 'Small caps'
 ];

 // DOM refs
 const inputEl = document.getElementById('inputText');
 const outputEl = document.getElementById('outputText');
 const styleGrid = document.getElementById('styleGrid');
 const copyBtn = document.getElementById('copyBtn');
 const clearBtn = document.getElementById('clearBtn');

 let activeStyle = 'Bold'; // default

 // ----- helper: convert text using style map -----
 function convertText(text, styleName) {
 if (!text) return '';
 const style = styleMap[styleName];
 if (!style) return text; // fallback

 const upperMap = style.chars;
 const lowerMap = style.lower;

 // Build full alphabet map (A-Z, a-z)
 const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
 const fancyChars = upperMap + lowerMap;

 let result = '';
 for (let i = 0; i < text.length; i++) {
 const char = text[i];
 const idx = alphabet.indexOf(char);
 if (idx !== -1) {
 result += fancyChars[idx];
 } else {
 result += char;
 }
 }
 return result;
 }

 // ----- update output based on input + active style -----
 function updateOutput() {
 const raw = inputEl.value || '';
 const converted = convertText(raw, activeStyle);
 outputEl.textContent = converted || '✨';
 }

 // ----- render style grid -----
 function renderStyles() {
 styleGrid.innerHTML = '';
 styleNames.forEach(name => {
 const card = document.createElement('div');
 card.className = 'style-card' + (name === activeStyle ? ' active' : '');
 card.dataset.style = name;

 // icon
 const icon = document.createElement('i');
 icon.className = 'fas fa-';
 if (name.includes('Bold')) icon.className += 'bold';
 else if (name.includes('Italic')) icon.className += 'italic';
 else if (name.includes('Script')) icon.className += 'pen-fancy';
 else if (name.includes('Monospace')) icon.className += 'code';
 else if (name.includes('Double')) icon.className += 'hashtag';
 else if (name.includes('Sans')) icon.className += 'font';
 else if (name.includes('Gothic') || name.includes('Fraktur')) icon.className += 'crown';
 else if (name.includes('Circled')) icon.className += 'circle';
 else if (name.includes('Parenthesis')) icon.className += 'bracket';
 else if (name.includes('Small')) icon.className += 'text-height';
 else icon.className += 'magic';

 // label
 const label = document.createElement('span');
 label.className = 'style-label';
 label.textContent = name;

 // preview (short)
 const preview = document.createElement('span');
 preview.className = 'style-preview';
 const sample = convertText('Abc', name);
 preview.textContent = sample.slice(0, 4) + (sample.length > 4 ? '…' : '');

 card.appendChild(icon);
 card.appendChild(label);
 card.appendChild(preview);

 card.addEventListener('click', function(e) {
 const styleName = this.dataset.style;
 if (styleName && styleName !== activeStyle) {
 // update active
 document.querySelectorAll('.style-card').forEach(c => c.classList.remove('active'));
 this.classList.add('active');
 activeStyle = styleName;
 updateOutput();
 }
 });

 styleGrid.appendChild(card);
 });
 }

 // ----- copy to clipboard -----
 function copyOutput() {
 const text = outputEl.textContent;
 if (!text || text === '✨') return;
 if (navigator.clipboard && navigator.clipboard.writeText) {
 navigator.clipboard.writeText(text).then(() => {
 // visual feedback
 const original = copyBtn.innerHTML;
 copyBtn.innerHTML = '<i class="fas fa-check"></i> Copied!';
 setTimeout(() => { copyBtn.innerHTML = original; }, 1600);
 }).catch(() => {
 fallbackCopy(text);
 });
 } else {
 fallbackCopy(text);
 }
 }

 function fallbackCopy(text) {
 const ta = document.createElement('textarea');
 ta.value = text;
 ta.style.position = 'fixed';
 ta.style.left = '-9999px';
 ta.style.top = '-9999px';
 document.body.appendChild(ta);
 ta.select();
 try {
 document.execCommand('copy');
 const original = copyBtn.innerHTML;
 copyBtn.innerHTML = '<i class="fas fa-check"></i> Copied!';
 setTimeout(() => { copyBtn.innerHTML = original; }, 1600);
 } catch (e) {
 alert('Could not copy. Please select and copy manually.');
 }
 document.body.removeChild(ta);
 }

 // ----- event listeners -----
 inputEl.addEventListener('input', updateOutput);
 clearBtn.addEventListener('click', function() {
 inputEl.value = '';
 updateOutput();
 inputEl.focus();
 });

 copyBtn.addEventListener('click', copyOutput);

 // initial render & set default output
 renderStyles();
 // set default active
 document.querySelectorAll('.style-card').forEach(c => {
 if (c.dataset.style === activeStyle) c.classList.add('active');
 });
 updateOutput();
 // if input empty, set a demo
 if (!inputEl.value) {
 inputEl.value = 'Fancy Text';
 updateOutput();
 }

 // extra: keyboard shortcut for clear (Escape)
 inputEl.addEventListener('keydown', function(e) {
 if (e.key === 'Escape') {
 this.blur();
 }
 });

 })();
 </script>
</body>
</html>
