      border-radius: 56px;
      padding: 2.5rem 2.8rem 3rem;
      box-shadow: 0 30px 60px -20px rgba(98, 55, 150, 0.25),
                  0 8px 28px rgba(0, 0, 0, 0.04);
      border: 1px solid rgba(255, 255, 255, 0.6);
      transition: all 0.2s ease;
    }

    @media (max-width: 600px) {
      .card {
        padding: 1.8rem 1.2rem 2rem;
        border-radius: 36px;
      }
    }

    h1 {
      font-size: 2.5rem;
      font-weight: 650;
      letter-spacing: -0.02em;
      background: linear-gradient(135deg, #3b1f6e, #7c3aed);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      margin-bottom: 0.35rem;
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .subhead {
      font-size: 1rem;
      color: #5b4a7a;
      font-weight: 400;
      margin-bottom: 2rem;
      border-left: 4px solid #a78bfa;
      padding-left: 1rem;
      background: rgba(167, 139, 250, 0.08);
      border-radius: 0 12px 12px 0;
      line-height: 1.5;
    }

    .input-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem 1rem;
      background: rgba(255, 255, 255, 0.5);
      padding: 1.2rem 1.5rem;
      border-radius: 40px;
      backdrop-filter: blur(4px);
      border: 1px solid rgba(255, 255, 255, 0.7);
      margin-bottom: 1.8rem;
      align-items: center;
    }

    .input-group label {
      font-weight: 500;
      color: #2d1b4e;
      font-size: 0.95rem;
      letter-spacing: 0.3px;
    }

    .input-group input[type="date"] {
      flex: 2 1 180px;
      padding: 0.7rem 1.2rem;
      border: 1px solid #d8cff0;
      border-radius: 60px;
      font-family: "Inter", sans-serif;
      font-size: 0.95rem;
      background: white;
      color: #1f143a;
      outline: none;
      transition: 0.2s;
      box-shadow: 0 2px 6px rgba(0,0,0,0.02);
    }

    .input-group input[type="date"]:focus {
      border-color: #7c3aed;
      box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.15);
    }

    .input-group button {
      background: #7c3aed;
      border: none;
      color: white;
      font-weight: 600;
      padding: 0.7rem 2rem;
      border-radius: 60px;
      font-size: 0.95rem;
      cursor: pointer;
      transition: all 0.15s;
      box-shadow: 0 8px 16px -6px rgba(124, 58, 237, 0.25);
      letter-spacing: 0.3px;
      border: 1px solid rgba(255,255,255,0.2);
      flex: 0 1 auto;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .input-group button:hover {
      background: #6d28d9;
      transform: scale(0.98);
      box-shadow: 0 6px 12px -4px rgba(124, 58, 237, 0.35);
    }

    .input-group button:active {
      background: #5b21b6;
      transform: scale(0.96);
    }

    .result-panel {
      background: rgba(255, 255, 255, 0.6);
      backdrop-filter: blur(4px);
      border-radius: 40px;
      padding: 1.8rem 1.8rem 1.5rem;
      margin: 1.2rem 0 2rem;
      border: 1px solid rgba(255,255,255,0.5);
      box-shadow: inset 0 1px 4px rgba(255,255,255,0.8);
    }

    .result-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
      gap: 0.8rem 0.6rem;
      text-align: center;
    }

    .result-item {
      background: rgba(255, 255, 255, 0.5);
      padding: 0.8rem 0.2rem;
      border-radius: 32px;
      backdrop-filter: blur(2px);
      border: 1px solid rgba(255,255,255,0.3);
    }

    .result-item .number {
      font-size: 1.8rem;
      font-weight: 650;
      color: #2d1b4e;
      line-height: 1.2;
      letter-spacing: -0.3px;
    }

    .result-item .label {
      font-size: 0.7rem;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: #5f4a7c;
      font-weight: 500;
      opacity: 0.8;
    }

    .result-item.accent {
      background: linear-gradient(135deg, #ede9fe, #d9c9ff);
      border-color: #b69cff;
    }

    .extra-details {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 0.6rem 1.5rem;
      margin-top: 1.2rem;
      font-size: 0.9rem;
      color: #2d1b4e;
      background: rgba(255,255,255,0.3);
      padding: 0.8rem 1.4rem;
      border-radius: 60px;
      backdrop-filter: blur(2px);
    }

    .extra-details span {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .extra-details .badge {
      background: #7c3aed20;
      padding: 0.2rem 0.8rem;
      border-radius: 30px;
      font-weight: 500;
      color: #4c2a7a;
    }

    .info-section {
      margin-top: 1.8rem;
      padding-top: 1.2rem;
      border-top: 2px dashed rgba(124, 58, 237, 0.15);
      display: flex;
      flex-wrap: wrap;
      gap: 1rem 2rem;
    }

    .info-section .howto {
      flex: 2 1 220px;
    }

    .info-section h3 {
      font-size: 0.9rem;
      font-weight: 600;
      color: #3b1f6e;
      letter-spacing: 0.3px;
      margin-bottom: 0.25rem;
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .info-section p {
      font-size: 0.9rem;
      color: #3d2b5a;
      line-height: 1.5;
      opacity: 0.85;
    }

    .info-section .badge-uptime {
      background: #10b98120;
      color: #0b6e4f;
      padding: 0.2rem 1.2rem;
      border-radius: 60px;
      font-size: 0.75rem;
      font-weight: 600;
      border: 1px solid #10b98140;
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }

    .footer-note {
      margin-top: 0.8rem;
      font-size: 0.75rem;
      color: #6e5b8a;
      text-align: right;
      letter-spacing: 0.2px;
    }

    /* 100% uptime badge */
    .uptime-badge {
      display: inline-block;
      background: #10b98118;
      border-radius: 60px;
      padding: 0.1rem 1rem;
      font-size: 0.7rem;
      font-weight: 500;
      color: #0c6b4b;
      border: 1px solid #10b98130;
    }
  </style>
</head>
<body>
  <div class="card">
    <h1>
      <span>📅 Age Calculator</span>
      <span class="uptime-badge">⚡ 100% uptime · no API</span>
    </h1>
    <div class="subhead">
      Find your exact age in years, months, days, hours, minutes, and seconds — down to the second.
    </div>

    <!-- input area -->
    <div class="input-group">
      <label for="birthday">Birth date</label>
      <input type="date" id="birthday" value="2000-01-01" aria-label="Select your birth date">
      <button id="calculateBtn">✨ Calculate</button>
    </div>

    <!-- results -->
    <div class="result-panel" id="resultPanel">
      <div class="result-grid" id="resultGrid">
        <div class="result-item accent"><span class="number" id="years">—</span><span class="label">Years</span></div>
        <div class="result-item"><span class="number" id="months">—</span><span class="label">Months</span></div>
        <div class="result-item"><span class="number" id="days">—</span><span class="label">Days</span></div>
        <div class="result-item"><span class="number" id="hours">—</span><span class="label">Hours</span></div>
        <div class="result-item"><span class="number" id="minutes">—</span><span class="label">Minutes</span></div>
        <div class="result-item"><span class="number" id="seconds">—</span><span class="label">Seconds</span></div>
      </div>
      <div class="extra-details">
        <span>🧾 <span id="totalDays">—</span> total days</span>
        <span>🕒 <span id="totalWeeks">—</span> weeks</span>
        <span class="badge" id="nextBirthday">🎂 next birthday: —</span>
      </div>
    </div>

    <!-- info + how to use -->
    <div class="info-section">
      <div class="howto">
        <h3>📖 How to use</h3>
        <p>Select your birth date using the date picker, then click “Calculate”. Your age will be shown in years, months, days, hours, minutes, and seconds. The tool runs 100% client-side — no data is sent anywhere.</p>
      </div>
      <div style="flex: 1 1 140px;">
        <h3>⚡ Fast & reliable</h3>
        <p style="display: flex; flex-wrap: wrap; gap: 6px 0;">No API keys, no external calls. Pure JavaScript. Works offline.</p>
        <div style="margin-top: 6px;"><span class="badge-uptime">✅ 100% uptime · zero latency</span></div>
      </div>
    </div>
    <div class="footer-note">
      <span>⏱️ real‑time · precise to the second</span>
    </div>
  </div>

  <script>
    (function() {
      "use strict";

      // DOM elements
      const birthdayInput = document.getElementById('birthday');
      const calcBtn = document.getElementById('calculateBtn');

      const yearsEl = document.getElementById('years');
      const monthsEl = document.getElementById('months');
      const daysEl = document.getElementById('days');
      const hoursEl = document.getElementById('hours');
      const minutesEl = document.getElementById('minutes');
      const secondsEl = document.getElementById('seconds');
      const totalDaysEl = document.getElementById('totalDays');
      const totalWeeksEl = document.getElementById('totalWeeks');
      const nextBirthdayEl = document.getElementById('nextBirthday');

      // helper: format number with leading zero if needed (for display)
      function padZero(n) {
        return n < 10 ? '0' + n : String(n);
      }

      // core calculation
      function calculateAge(birthDate) {
        const now = new Date(); // current moment

        // clone to avoid mutation
        const birth = new Date(birthDate);
        if (isNaN(birth.getTime())) {
          return null;
        }

        // ---- difference in milliseconds ----
        const diffMs = now.getTime() - birth.getTime();
        if (diffMs < 0) {
          return null; // future date
        }

        // ---- extract components ----
        const totalSeconds = Math.floor(diffMs / 1000);
        const totalMinutes = Math.floor(totalSeconds / 60);
        const totalHours = Math.floor(totalMinutes / 60);
        const totalDays = Math.floor(totalHours / 24);

        // ---- years, months, days (calendar age) ----
        let years = now.getFullYear() - birth.getFullYear();
        let months = now.getMonth() - birth.getMonth();
        let days = now.getDate() - birth.getDate();

        // adjust for negative days
        if (days < 0) {
          const prevMonth = new Date(now.getFullYear(), now.getMonth(), 0);
          days += prevMonth.getDate();
          months--;
        }

        // adjust for negative months
        if (months < 0) {
          years--;
          months += 12;
        }

        // ---- hours, minutes, seconds from current time ----
        const hours = now.getHours();
        const minutes = now.getMinutes();
        const seconds = now.getSeconds();

        // ---- total weeks ----
        const totalWeeks = Math.floor(totalDays / 7);

        // ---- next birthday (approximate) ----
        let nextBirth = new Date(now.getFullYear(), birth.getMonth(), birth.getDate());
        if (nextBirth < now) {
          nextBirth.setFullYear(nextBirth.getFullYear() + 1);
        }
        const diffToNext = nextBirth.getTime() - now.getTime();
        let nextBirthdayStr = '';
        if (diffToNext > 0) {
          const d = Math.floor(diffToNext / (1000 * 60 * 60 * 24));
          const h = Math.floor((diffToNext % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
          const m = Math.floor((diffToNext % (1000 * 60 * 60)) / (1000 * 60));
          nextBirthdayStr = `${d}d ${h}h ${m}m`;
        } else {
          nextBirthdayStr = '🎉 today!';
        }

        return {
          years, months, days,
          hours, minutes, seconds,
          totalDays,
          totalWeeks,
          nextBirthday: nextBirthdayStr,
          // extra: total seconds for precision
          totalSeconds
        };
      }

      function updateDisplay(result) {
        if (!result) {
          // invalid or future date
          yearsEl.textContent = '—';
          monthsEl.textContent = '—';
          daysEl.textContent = '—';
          hoursEl.textContent = '—';
          minutesEl.textContent = '—';
          secondsEl.textContent = '—';
          totalDaysEl.textContent = '—';
          totalWeeksEl.textContent = '—';
          nextBirthdayEl.textContent = '🎂 invalid date';
          return;
        }

        yearsEl.textContent = result.years;
        monthsEl.textContent = result.months;
        daysEl.textContent = result.days;
        hoursEl.textContent = result.hours;
        minutesEl.textContent = result.minutes;
        secondsEl.textContent = result.seconds;
        totalDaysEl.textContent = result.totalDays.toLocaleString();
        totalWeeksEl.textContent = result.totalWeeks.toLocaleString();
        nextBirthdayEl.textContent = `🎂 ${result.nextBirthday}`;
      }

      function handleCalculate() {
        const rawDate = birthdayInput.value;
        if (!rawDate) {
          // fallback: set to default if empty
          birthdayInput.value = '2000-01-01';
          const fallbackDate = new Date('2000-01-01');
          const result = calculateAge(fallbackDate);
          updateDisplay(result);
          return;
        }

        const parts = rawDate.split('-');
        if (parts.length !== 3) {
          updateDisplay(null);
          return;
        }
        const year = parseInt(parts[0], 10);
        const month = parseInt(parts[1], 10) - 1; // 0-index
        const day = parseInt(parts[2], 10);
        if (isNaN(year) || isNaN(month) || isNaN(day)) {
          updateDisplay(null);
          return;
        }

        const birthDate = new Date(year, month, day);
        if (isNaN(birthDate.getTime())) {
          updateDisplay(null);
          return;
        }

        const result = calculateAge(birthDate);
        if (!result) {
          // future date
          updateDisplay(null);
          return;
        }
        updateDisplay(result);
      }

      // ---- set default date & auto-calculate ----
      function setDefaultAndCalculate() {
        // set default date to 2000-01-01 if empty
        if (!birthdayInput.value) {
          birthdayInput.value = '2000-01-01';
        }
        handleCalculate();
      }

      // ---- event listeners ----
      calcBtn.addEventListener('click', handleCalculate);
      // also recalculate when user changes date (optional but friendly)
      birthdayInput.addEventListener('change', handleCalculate);

      // ---- initial load ----
      setDefaultAndCalculate();

      // ---- live update every second (optional, but keeps seconds fresh) ----
      let liveInterval = null;
      function startLiveUpdate() {
        if (liveInterval) clearInterval(liveInterval);
        liveInterval = setInterval(() => {
          // only if date is valid, recalc to keep seconds updated
          const raw = birthdayInput.value;
          if (!raw) return;
          const parts = raw.split('-');
          if (parts.length !== 3) return;
          const year = parseInt(parts[0], 10);
          const month = parseInt(parts[1], 10) - 1;
          const day = parseInt(parts[2], 10);
          if (isNaN(year) || isNaN(month) || isNaN(day)) return;
          const birthDate = new Date(year, month, day);
          if (isNaN(birthDate.getTime())) return;
          const result = calculateAge(birthDate);
          if (result) {
            updateDisplay(result);
          }
        }, 1000);
      }

      startLiveUpdate();

      // clean interval on page unload (good practice)
      window.addEventListener('beforeunload', function() {
        if (liveInterval) clearInterval(liveInterval);
      });

      // if user changes date, we keep interval running (recalc each second)
      // we also recalc on change, so it's fine.

    })();
  </script>
</body>
</html>
