<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.5">
  <title>Math Tools · modern calculator suite</title>
  <meta name="description" content="A clean, fast suite of math tools: percentage, BMI, unit converter, quadratic solver and more. No API keys, 100% functional.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&display=swap" rel="stylesheet">
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }
    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background: linear-gradient(145deg, #f6f9fc 0%, #edf2f7 100%);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 1.5rem;
      color: #1a202c;
    }
    .card {
      max-width: 1280px;
      width: 100%;
      background: rgba(255,255,255,0.70);
      backdrop-filter: blur(4px);
      -webkit-backdrop-filter: blur(4px);
      border-radius: 2.5rem;
      padding: 2rem 2.5rem;
      box-shadow: 0 20px 40px -12px rgba(0,0,0,0.15), 0 8px 24px -6px rgba(0,20,30,0.08);
      border: 1px solid rgba(255,255,255,0.6);
      transition: all 0.2s ease;
    }
    h1 {
      font-size: 2.4rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      background: linear-gradient(135deg, #0b2b44, #1b4a6b);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      display: inline-block;
      margin-bottom: 0.25rem;
    }
    .subhead {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 2rem;
      border-bottom: 1px solid rgba(0,0,0,0.05);
      padding-bottom: 0.75rem;
    }
    .subhead p {
      font-size: 1rem;
      color: #2d4a6a;
      background: rgba(200, 222, 240, 0.3);
      padding: 0.3rem 1rem;
      border-radius: 40px;
      font-weight: 500;
      backdrop-filter: blur(2px);
      border: 1px solid rgba(255,255,255,0.3);
    }
    .tool-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 1.8rem;
      margin-top: 0.5rem;
    }
    .tool-card {
      background: rgba(255,255,255,0.7);
      backdrop-filter: blur(2px);
      -webkit-backdrop-filter: blur(2px);
      border-radius: 1.8rem;
      padding: 1.5rem 1.5rem 1.8rem;
      box-shadow: 0 4px 12px rgba(0, 20, 30, 0.04);
      border: 1px solid rgba(255,255,255,0.8);
      transition: transform 0.15s ease, box-shadow 0.2s;
      display: flex;
      flex-direction: column;
    }
    .tool-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 16px 28px -12px rgba(0, 40, 70, 0.12);
      background: rgba(255,255,255,0.85);
      border-color: #cbddee;
    }
    .tool-title {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 600;
      font-size: 1.3rem;
      color: #0b2b44;
      margin-bottom: 0.9rem;
      letter-spacing: -0.01em;
    }
    .tool-title span {
      background: #d9e7f5;
      border-radius: 40px;
      padding: 0.1rem 0.7rem;
      font-size: 0.8rem;
      font-weight: 600;
      color: #1a4a6e;
    }
    .tool-body {
      display: flex;
      flex-direction: column;
      gap: 0.8rem;
      flex: 1;
    }
    .input-group {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.5rem;
    }
    .input-group label {
      font-size: 0.85rem;
      font-weight: 500;
      color: #1f3b54;
      min-width: 50px;
    }
    .input-group input, .input-group select {
      background: white;
      border: 1px solid #dce6ef;
      border-radius: 40px;
      padding: 0.5rem 0.9rem;
      font-size: 0.9rem;
      flex: 1;
      min-width: 90px;
      outline: none;
      transition: 0.15s;
      font-family: 'Inter', sans-serif;
      color: #0a263a;
    }
    .input-group input:focus, .input-group select:focus {
      border-color: #3b7eb0;
      box-shadow: 0 0 0 3px rgba(59, 126, 176, 0.15);
    }
    .input-group input[type="number"] {
      -moz-appearance: textfield;
    }
    .input-group input[type="number"]::-webkit-outer-spin-button,
    .input-group input[type="number"]::-webkit-inner-spin-button {
      -webkit-appearance: none;
      margin: 0;
    }
    .action-btn {
      background: #eaf1f9;
      border: none;
      border-radius: 40px;
      padding: 0.5rem 1.2rem;
      font-weight: 600;
      font-size: 0.85rem;
      color: #1b4a6b;
      cursor: pointer;
      transition: 0.15s;
      border: 1px solid transparent;
      align-self: flex-start;
      letter-spacing: 0.3px;
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }
    .action-btn:hover {
      background: #cfe0ef;
      border-color: #9bbcd9;
      color: #0b2b44;
      transform: scale(0.97);
    }
    .action-btn.primary {
      background: #1b4a6b;
      color: white;
      box-shadow: 0 4px 8px -4px rgba(20, 70, 110, 0.2);
    }
    .action-btn.primary:hover {
      background: #0f3a57;
      box-shadow: 0 6px 12px -6px rgba(20, 70, 110, 0.3);
    }
    .result-box {
      background: rgba(220, 235, 248, 0.3);
      padding: 0.6rem 1rem;
      border-radius: 40px;
      margin-top: 0.3rem;
      font-size: 0.95rem;
      font-weight: 500;
      color: #10344f;
      border: 1px solid rgba(255,255,255,0.5);
      word-break: break-word;
    }
    .result-box strong {
      font-weight: 700;
      color: #05212f;
    }
    .info-note {
      margin-top: 2.2rem;
      background: rgba(235, 245, 252, 0.5);
      backdrop-filter: blur(4px);
      padding: 0.8rem 1.5rem;
      border-radius: 60px;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      border: 1px solid rgba(255,255,255,0.6);
      font-size: 0.9rem;
      color: #1a405a;
    }
    .info-note span:first-child {
      font-weight: 500;
      background: rgba(27, 74, 107, 0.06);
      padding: 0.2rem 1rem;
      border-radius: 40px;
    }
    .info-note span:last-child {
      opacity: 0.8;
    }
    hr {
      border: none;
      border-top: 1px solid rgba(0,0,0,0.04);
      margin: 0.2rem 0 0.8rem;
    }
    @media (max-width: 640px) {
      .card { padding: 1.5rem; }
      h1 { font-size: 2rem; }
      .tool-grid { gap: 1.2rem; }
    }
  </style>
</head>
<body>
  <div class="card">
    <div class="subhead">
      <h1>🧮 Math Tools</h1>
      <p>⚡ fast · no API · 100% functional</p>
    </div>

    <div class="tool-grid" id="toolGrid">
      <!-- 1. PERCENTAGE CALCULATOR -->
      <div class="tool-card">
        <div class="tool-title"><span>%</span> Percentage</div>
        <div class="tool-body">
          <div class="input-group"><label>Value</label><input type="number" id="pVal" value="200" step="any"></div>
          <div class="input-group"><label>Percent</label><input type="number" id="pPct" value="15" step="any"></div>
          <button class="action-btn primary" id="calcPct">Calculate</button>
          <div class="result-box" id="pResult"><strong>30</strong> (15% of 200)</div>
        </div>
      </div>

      <!-- 2. BMI CALCULATOR -->
      <div class="tool-card">
        <div class="tool-title"><span>⚖️</span> BMI</div>
        <div class="tool-body">
          <div class="input-group"><label>Weight (kg)</label><input type="number" id="bmiWeight" value="70" step="0.1"></div>
          <div class="input-group"><label>Height (cm)</label><input type="number" id="bmiHeight" value="175" step="0.1"></div>
          <button class="action-btn primary" id="calcBmi">Calculate</button>
          <div class="result-box" id="bmiResult"><strong>22.9</strong> · Normal</div>
        </div>
      </div>

      <!-- 3. UNIT CONVERTER (length) -->
      <div class="tool-card">
        <div class="tool-title"><span>📐</span> Unit converter</div>
        <div class="tool-body">
          <div class="input-group"><label>Value</label><input type="number" id="convVal" value="1" step="any"></div>
          <div class="input-group">
            <label>From</label>
            <select id="convFrom"><option value="m">m</option><option value="km">km</option><option value="ft">ft</option><option value="mi">mi</option></select>
          </div>
          <div class="input-group">
            <label>To</label>
            <select id="convTo"><option value="m">m</option><option value="km" selected>km</option><option value="ft">ft</option><option value="mi">mi</option></select>
          </div>
          <button class="action-btn primary" id="calcConv">Convert</button>
          <div class="result-box" id="convResult"><strong>0.001</strong> km</div>
        </div>
      </div>

      <!-- 4. QUADRATIC SOLVER (ax²+bx+c=0) -->
      <div class="tool-card">
        <div class="tool-title"><span>✖️²</span> Quadratic</div>
        <div class="tool-body">
          <div class="input-group"><label>a</label><input type="number" id="qA" value="1" step="any"></div>
          <div class="input-group"><label>b</label><input type="number" id="qB" value="-3" step="any"></div>
          <div class="input-group"><label>c</label><input type="number" id="qC" value="2" step="any"></div>
          <button class="action-btn primary" id="calcQuad">Solve</button>
          <div class="result-box" id="quadResult"><strong>x₁=2.0</strong> · x₂=1.0</div>
        </div>
      </div>
    </div>

    <!-- info & usage -->
    <div class="info-note">
      <span>📘 How to use: fill values, click calculate · all tools work offline</span>
      <span>✨ clean · modern · fast</span>
    </div>
  </div>

  <script>
    (function() {
      "use strict";

      // ----- PERCENTAGE -----
      const pVal = document.getElementById('pVal');
      const pPct = document.getElementById('pPct');
      const pResult = document.getElementById('pResult');
      document.getElementById('calcPct').addEventListener('click', function() {
        const val = parseFloat(pVal.value);
        const pct = parseFloat(pPct.value);
        if (isNaN(val) || isNaN(pct)) { pResult.innerHTML = '<strong>⚠️</strong> enter valid numbers'; return; }
        const result = (pct / 100) * val;
        pResult.innerHTML = `<strong>${result.toFixed(4)}</strong> (${pct}% of ${val})`;
      });

      // ----- BMI -----
      const bmiWeight = document.getElementById('bmiWeight');
      const bmiHeight = document.getElementById('bmiHeight');
      const bmiResult = document.getElementById('bmiResult');
      document.getElementById('calcBmi').addEventListener('click', function() {
        const w = parseFloat(bmiWeight.value);
        const h = parseFloat(bmiHeight.value) / 100; // cm -> m
        if (isNaN(w) || isNaN(h) || h <= 0) { bmiResult.innerHTML = '<strong>⚠️</strong> enter valid weight/height'; return; }
        const bmi = w / (h * h);
        let cat = '';
        if (bmi < 18.5) cat = 'Underweight';
        else if (bmi < 25) cat = 'Normal';
        else if (bmi < 30) cat = 'Overweight';
        else cat = 'Obese';
        bmiResult.innerHTML = `<strong>${bmi.toFixed(1)}</strong> · ${cat}`;
      });

      // ----- UNIT CONVERTER (length) -----
      const convVal = document.getElementById('convVal');
      const convFrom = document.getElementById('convFrom');
      const convTo = document.getElementById('convTo');
      const convResult = document.getElementById('convResult');
      // conversion factors to meter
      const unitToMeter = { m: 1, km: 1000, ft: 0.3048, mi: 1609.34 };
      document.getElementById('calcConv').addEventListener('click', function() {
        const val = parseFloat(convVal.value);
        if (isNaN(val)) { convResult.innerHTML = '<strong>⚠️</strong> enter a number'; return; }
        const fromUnit = convFrom.value;
        const toUnit = convTo.value;
        const meters = val * unitToMeter[fromUnit];
        const result = meters / unitToMeter[toUnit];
        convResult.innerHTML = `<strong>${result.toFixed(6)}</strong> ${toUnit}`;
      });

      // ----- QUADRATIC SOLVER -----
      const qA = document.getElementById('qA');
      const qB = document.getElementById('qB');
      const qC = document.getElementById('qC');
      const quadResult = document.getElementById('quadResult');
      document.getElementById('calcQuad').addEventListener('click', function() {
        const a = parseFloat(qA.value);
        const b = parseFloat(qB.value);
        const c = parseFloat(qC.value);
        if (isNaN(a) || isNaN(b) || isNaN(c)) { quadResult.innerHTML = '<strong>⚠️</strong> enter coefficients'; return; }
        if (a === 0) { quadResult.innerHTML = '<strong>⚠️</strong> a cannot be 0 (not quadratic)'; return; }
        const disc = b*b - 4*a*c;
        if (disc < 0) {
          quadResult.innerHTML = '<strong>⚠️</strong> no real roots (discriminant < 0)';
          return;
        }
        const sqrtD = Math.sqrt(disc);
        const x1 = (-b + sqrtD) / (2*a);
        const x2 = (-b - sqrtD) / (2*a);
        let display = '';
        if (x1 === x2) display = `<strong>x = ${x1.toFixed(4)}</strong> (double root)`;
        else display = `<strong>x₁ = ${x1.toFixed(4)}</strong> · x₂ = ${x2.toFixed(4)}`;
        quadResult.innerHTML = display;
      });

      // ----- set initial results on load (make them match default values) -----
      // Percentage
      (function initPct() {
        const val = parseFloat(pVal.value) || 200;
        const pct = parseFloat(pPct.value) || 15;
        const result = (pct / 100) * val;
        pResult.innerHTML = `<strong>${result.toFixed(4)}</strong> (${pct}% of ${val})`;
      })();
      // BMI
      (function initBmi() {
        const w = parseFloat(bmiWeight.value) || 70;
        const h = (parseFloat(bmiHeight.value) || 175) / 100;
        if (h > 0) {
          const bmi = w / (h * h);
          let cat = '';
          if (bmi < 18.5) cat = 'Underweight';
          else if (bmi < 25) cat = 'Normal';
          else if (bmi < 30) cat = 'Overweight';
          else cat = 'Obese';
          bmiResult.innerHTML = `<strong>${bmi.toFixed(1)}</strong> · ${cat}`;
        }
      })();
      // Unit converter
      (function initConv() {
        const val = parseFloat(convVal.value) || 1;
        const from = convFrom.value || 'm';
        const to = convTo.value || 'km';
        const meters = val * unitToMeter[from];
        const result = meters / unitToMeter[to];
        convResult.innerHTML = `<strong>${result.toFixed(6)}</strong> ${to}`;
      })();
      // Quadratic
      (function initQuad() {
        const a = parseFloat(qA.value) || 1;
        const b = parseFloat(qB.value) || -3;
        const c = parseFloat(qC.value) || 2;
        if (a !== 0) {
          const disc = b*b - 4*a*c;
          if (disc >= 0) {
            const sqrtD = Math.sqrt(disc);
            const x1 = (-b + sqrtD) / (2*a);
            const x2 = (-b - sqrtD) / (2*a);
            let display = '';
            if (x1 === x2) display = `<strong>x = ${x1.toFixed(4)}</strong> (double root)`;
            else display = `<strong>x₁ = ${x1.toFixed(4)}</strong> · x₂ = ${x2.toFixed(4)}`;
            quadResult.innerHTML = display;
          }
        }
      })();

    })();
  </script>
</body>
</html>
