<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Finance Tools · modern calculator suite</title>
  <!-- SEO meta -->
  <meta name="description" content="Free online finance tools: compound interest, loan payment, investment growth, currency conversion. No API keys, 100% functional, fast & clean.">
  <link rel="canonical" href="https://financetools.example/">
  <!-- Font & icons (Font Awesome + Google Font) -->
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700&display=swap" rel="stylesheet">
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', sans-serif;
      background: linear-gradient(145deg, #f6f9fc 0%, #eef2f7 100%);
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      padding: 2rem 1rem;
      color: #1b2a3a;
    }

    /* main card – glassmorphism style */
    .tool-wrapper {
      max-width: 1280px;
      width: 100%;
      background: rgba(255,255,255,0.60);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-radius: 48px;
      padding: 2.5rem 2.8rem;
      box-shadow: 0 25px 50px -10px rgba(0,20,40,0.25), 0 0 0 1px rgba(255,255,255,0.5);
      transition: all 0.2s ease;
    }

    /* header */
    .header {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 2rem;
    }

    .header h1 {
      font-size: 2.2rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      background: linear-gradient(135deg, #1f3a5f, #2b5a8a);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .header i {
      background: #1f3a5f10;
      padding: 0.6rem 1.2rem;
      border-radius: 60px;
      font-size: 1rem;
      font-weight: 500;
      color: #1f3a5f;
      border: 1px solid #ffffff80;
      box-shadow: 0 4px 8px rgba(0,0,0,0.02);
    }

    /* description / how-to */
    .info-panel {
      background: rgba(255,255,255,0.5);
      backdrop-filter: blur(4px);
      -webkit-backdrop-filter: blur(4px);
      border-radius: 28px;
      padding: 1.6rem 2rem;
      margin-bottom: 2.8rem;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1.5rem 2.5rem;
      border: 1px solid #ffffffd0;
      box-shadow: 0 6px 14px rgba(0, 20, 30, 0.04);
    }

    .info-panel .desc {
      flex: 2;
      min-width: 200px;
    }

    .info-panel .desc p {
      font-size: 1rem;
      line-height: 1.6;
      color: #1e3347;
      font-weight: 450;
    }

    .info-panel .desc strong {
      font-weight: 600;
      color: #0b253b;
    }

    .info-panel .badge {
      display: flex;
      gap: 0.5rem 1.2rem;
      flex-wrap: wrap;
      background: #d9e6f2;
      padding: 0.5rem 1.4rem;
      border-radius: 60px;
      font-size: 0.9rem;
      font-weight: 500;
      color: #0f2a41;
    }

    .info-panel .badge i {
      margin-right: 6px;
      color: #1f6390;
    }

    /* tool grid */
    .tools-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 2rem 1.8rem;
      margin-top: 0.8rem;
    }

    .tool-card {
      background: rgba(255,255,255,0.7);
      backdrop-filter: blur(4px);
      -webkit-backdrop-filter: blur(4px);
      border-radius: 32px;
      padding: 1.8rem 1.5rem 1.8rem;
      box-shadow: 0 10px 20px -8px rgba(0,20,40,0.08);
      transition: all 0.2s ease;
      border: 1px solid #ffffffd0;
      display: flex;
      flex-direction: column;
    }

    .tool-card:hover {
      transform: translateY(-5px);
      box-shadow: 0 20px 30px -12px rgba(0,30,60,0.15);
      background: rgba(255,255,255,0.8);
      border-color: #ffffff;
    }

    .tool-card h3 {
      font-size: 1.3rem;
      font-weight: 600;
      margin-bottom: 0.75rem;
      color: #1b3b5c;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .tool-card h3 i {
      font-size: 1.4rem;
      color: #2b6c9e;
      width: 2rem;
    }

    .tool-card .input-group {
      display: flex;
      flex-direction: column;
      gap: 0.6rem;
      margin: 0.6rem 0 0.8rem;
    }

    .tool-card label {
      font-size: 0.8rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.03em;
      color: #2f4a66;
      margin-top: 0.25rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .tool-card input {
      background: #ffffffd0;
      border: 1px solid #dbe5ef;
      border-radius: 40px;
      padding: 0.7rem 1rem;
      font-size: 0.95rem;
      font-weight: 500;
      color: #0e263b;
      outline: none;
      transition: all 0.15s;
      font-family: 'Inter', sans-serif;
      width: 100%;
    }

    .tool-card input:focus {
      border-color: #2b7bb0;
      background: #ffffff;
      box-shadow: 0 0 0 3px #a0c9e8;
    }

    .tool-card .result-box {
      background: #e3edf7;
      border-radius: 40px;
      padding: 0.6rem 1.2rem;
      margin-top: 0.7rem;
      font-weight: 600;
      font-size: 1.2rem;
      color: #0d314b;
      text-align: center;
      letter-spacing: -0.01em;
      border: 1px solid #ffffff;
      word-break: break-word;
      min-height: 3.2rem;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .tool-card .result-box small {
      font-weight: 400;
      font-size: 0.75rem;
      color: #2f577b;
      margin-left: 0.3rem;
    }

    .btn-calc {
      background: #1f4a70;
      border: none;
      border-radius: 40px;
      padding: 0.75rem 0.6rem;
      font-weight: 600;
      font-size: 0.95rem;
      color: white;
      margin: 1rem 0 0.2rem;
      cursor: pointer;
      transition: 0.15s;
      border: 1px solid #346f9e;
      box-shadow: 0 4px 8px rgba(0,30,60,0.08);
      letter-spacing: 0.3px;
    }

    .btn-calc:hover {
      background: #1d5f8b;
      transform: scale(0.98);
      box-shadow: 0 8px 14px rgba(0,40,70,0.15);
    }

    .btn-calc:active {
      background: #13416b;
      transform: scale(0.96);
    }

    .footnote {
      margin-top: 3rem;
      text-align: center;
      font-size: 0.85rem;
      color: #3b5c7a;
      border-top: 1px solid #ffffffb0;
      padding-top: 1.8rem;
      letter-spacing: 0.2px;
      font-weight: 450;
    }

    .footnote i {
      margin: 0 4px;
      color: #346f9e;
    }

    @media (max-width: 700px) {
      .tool-wrapper { padding: 1.8rem 1.2rem; }
      .header h1 { font-size: 1.8rem; }
      .info-panel { flex-direction: column; align-items: flex-start; }
    }
  </style>
</head>
<body>
<div class="tool-wrapper">
  <div class="header">
    <h1><i class="fas fa-coins" style="margin-right: 12px; background: linear-gradient(145deg, #1f3a5f, #3274a3); -webkit-background-clip: text; -webkit-text-fill-color: transparent;"></i> Finance Tools</h1>
    <i class="fas fa-bolt" style="background: #d4e3f2;">  fast · no API</i>
  </div>

  <!-- Info & how-to -->
  <div class="info-panel">
    <div class="desc">
      <p><strong><i class="fas fa-circle-info" style="margin-right: 6px; color: #1f6390;"></i> How to use:</strong> Fill in the numbers, click <strong>“Calculate”</strong> — instant results. All tools are self-contained, no external API. Refresh or recalc anytime.</p>
    </div>
    <div class="badge">
      <span><i class="fas fa-calculator"></i> 4 tools</span>
      <span><i class="fas fa-gauge-high"></i> real‑time</span>
      <span><i class="fas fa-lock"></i> private</span>
    </div>
  </div>

  <!-- Tool grid -->
  <div class="tools-grid" id="toolGrid">
    <!-- 1. Compound Interest -->
    <div class="tool-card" id="toolCompound">
      <h3><i class="fas fa-chart-line"></i> Compound</h3>
      <div class="input-group">
        <label>Principal ($) <input type="number" id="compPrincipal" value="1000" step="100"></label>
        <label>Rate (%) <input type="number" id="compRate" value="5" step="0.1"></label>
        <label>Years <input type="number" id="compYears" value="10" step="1"></label>
      </div>
      <button class="btn-calc" data-tool="compound"><i class="fas fa-play"></i> Calculate</button>
      <div class="result-box" id="compResult">$1,628.89</div>
    </div>

    <!-- 2. Loan Payment (monthly) -->
    <div class="tool-card" id="toolLoan">
      <h3><i class="fas fa-hand-holding-dollar"></i> Loan</h3>
      <div class="input-group">
        <label>Loan ($) <input type="number" id="loanAmount" value="20000" step="1000"></label>
        <label>Rate (%) <input type="number" id="loanRate" value="4.5" step="0.1"></label>
        <label>Years <input type="number" id="loanYears" value="5" step="1"></label>
      </div>
      <button class="btn-calc" data-tool="loan"><i class="fas fa-play"></i> Calculate</button>
      <div class="result-box" id="loanResult">$372.86</div>
    </div>

    <!-- 3. Investment Growth (future value of periodic deposits) -->
    <div class="tool-card" id="toolInvestment">
      <h3><i class="fas fa-piggy-bank"></i> Growth</h3>
      <div class="input-group">
        <label>Monthly ($) <input type="number" id="invMonthly" value="200" step="10"></label>
        <label>Rate (%) <input type="number" id="invRate" value="6" step="0.1"></label>
        <label>Years <input type="number" id="invYears" value="15" step="1"></label>
      </div>
      <button class="btn-calc" data-tool="investment"><i class="fas fa-play"></i> Calculate</button>
      <div class="result-box" id="invResult">$58,148</div>
    </div>

    <!-- 4. Currency Converter (static rates, no API) -->
    <div class="tool-card" id="toolCurrency">
      <h3><i class="fas fa-dollar-sign"></i> Converter</h3>
      <div class="input-group">
        <label>USD <input type="number" id="curUsd" value="100" step="1"></label>
        <label>to EUR <input type="number" id="curEur" value="0.92" step="0.01" style="background: #eaf1f9;"></label>
        <label style="font-size:0.7rem; opacity:0.7; justify-content:center;">1 USD ≈ 0.92 EUR · 1 EUR ≈ 1.09 USD</label>
      </div>
      <button class="btn-calc" data-tool="currency"><i class="fas fa-play"></i> Convert</button>
      <div class="result-box" id="curResult">€ 92.00</div>
    </div>
  </div>

  <div class="footnote">
    <i class="fas fa-rotate-right"></i> all calculations are client‑side &bull; results update on click &bull; designed for clarity
  </div>
</div>

<script>
  (function() {
    "use strict";

    // ---- DOM refs ----
    // compound
    const compP = document.getElementById('compPrincipal');
    const compR = document.getElementById('compRate');
    const compY = document.getElementById('compYears');
    const compRes = document.getElementById('compResult');

    // loan
    const loanAmt = document.getElementById('loanAmount');
    const loanRate = document.getElementById('loanRate');
    const loanYears = document.getElementById('loanYears');
    const loanRes = document.getElementById('loanResult');

    // investment (future value of monthly deposits)
    const invMonthly = document.getElementById('invMonthly');
    const invRate = document.getElementById('invRate');
    const invYears = document.getElementById('invYears');
    const invRes = document.getElementById('invResult');

    // currency
    const curUsd = document.getElementById('curUsd');
    const curEur = document.getElementById('curEur');
    const curRes = document.getElementById('curResult');

    // ---- helper: parse float safely ----
    function getVal(el) { return parseFloat(el.value) || 0; }

    // ---- calculation functions (all pure) ----
    function calcCompound(p, r, y) {
      if (p <= 0 || r <= 0 || y <= 0) return 0;
      const rate = r / 100;
      return p * Math.pow(1 + rate, y);
    }

    function calcLoanPayment(principal, annualRate, years) {
      if (principal <= 0 || annualRate <= 0 || years <= 0) return 0;
      const monthlyRate = annualRate / 100 / 12;
      const months = years * 12;
      if (monthlyRate === 0) return principal / months;
      return principal * monthlyRate * Math.pow(1 + monthlyRate, months) / (Math.pow(1 + monthlyRate, months) - 1);
    }

    function calcInvestmentFuture(monthly, annualRate, years) {
      if (monthly <= 0 || annualRate <= 0 || years <= 0) return 0;
      const monthlyRate = annualRate / 100 / 12;
      const months = years * 12;
      if (monthlyRate === 0) return monthly * months;
      // future value of annuity (deposits at end of each month)
      return monthly * (Math.pow(1 + monthlyRate, months) - 1) / monthlyRate;
    }

    // currency: usd to eur (static rate)
    function convertCurrency(usd, rateEur) {
      if (usd <= 0 || rateEur <= 0) return 0;
      return usd * rateEur;
    }

    // ---- render with format ----
    function formatCurrency(value, decimals = 2) {
      if (!isFinite(value)) return '0.00';
      return value.toFixed(decimals);
    }

    // ---- update functions ----
    function updateCompound() {
      const p = getVal(compP);
      const r = getVal(compR);
      const y = getVal(compY);
      if (p <= 0 || r < 0 || y <= 0) { compRes.textContent = '—'; return; }
      const result = calcCompound(p, r, y);
      compRes.textContent = '$ ' + formatCurrency(result);
    }

    function updateLoan() {
      const p = getVal(loanAmt);
      const r = getVal(loanRate);
      const y = getVal(loanYears);
      if (p <= 0 || r < 0 || y <= 0) { loanRes.textContent = '—'; return; }
      const result = calcLoanPayment(p, r, y);
      loanRes.textContent = '$ ' + formatCurrency(result);
    }

    function updateInvestment() {
      const m = getVal(invMonthly);
      const r = getVal(invRate);
      const y = getVal(invYears);
      if (m <= 0 || r < 0 || y <= 0) { invRes.textContent = '—'; return; }
      const result = calcInvestmentFuture(m, r, y);
      invRes.textContent = '$ ' + formatCurrency(result, 0);
    }

    function updateCurrency() {
      const usd = getVal(curUsd);
      const eurRate = getVal(curEur);
      if (usd < 0 || eurRate < 0) { curRes.textContent = '—'; return; }
      const result = convertCurrency(usd, eurRate);
      curRes.textContent = '€ ' + formatCurrency(result);
    }

    // ---- attach events to all "Calculate" buttons ----
    document.querySelectorAll('.btn-calc').forEach(btn => {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        const tool = this.getAttribute('data-tool');
        switch (tool) {
          case 'compound': updateCompound(); break;
          case 'loan': updateLoan(); break;
          case 'investment': updateInvestment(); break;
          case 'currency': updateCurrency(); break;
          default: break;
        }
      });
    });

    // ---- also recalc on Enter key (input fields) ----
    const inputs = document.querySelectorAll('input');
    inputs.forEach(inp => {
      inp.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          const card = this.closest('.tool-card');
          if (!card) return;
          const btn = card.querySelector('.btn-calc');
          if (btn) btn.click();
        }
      });
    });

    // ---- initial calculation on load ----
    window.addEventListener('DOMContentLoaded', function() {
      updateCompound();
      updateLoan();
      updateInvestment();
      updateCurrency();
    });

    // (optional) small extra: auto-update currency when usd or rate changes? we keep it explicit via button.
    // but we also bind "input" to update preview? We'll keep it explicit for clarity.
    // But add a tiny helper: click on label trigger? not needed.

  })();
</script>
</body>
</html>
