      .brand h1 { font-size: 1.6rem; }
      .stat-value { font-size: 1.4rem; }
    }

    /* quick responsive fix */
    .flex-wrap { flex-wrap: wrap; }
  </style>
</head>
<body>
  <div class="app-wrapper">

    <!-- header -->
    <div class="brand">
      <i class="fas fa-feather-alt"></i>
      <h1>Writing Tools <span>pro</span></h1>
    </div>
    <div class="subhead">
      <i class="fas fa-magic" style="margin-right: 10px; color: #6c4cff;"></i> 
      zero API · real‑time · 100% private
    </div>

    <!-- main tool card -->
    <div class="tool-card">

      <!-- tool selection -->
      <div class="tool-grid" id="toolGrid">
        <button class="tool-btn active" data-tool="wordcount"><i class="fas fa-calculator"></i> Word counter</button>
        <button class="tool-btn" data-tool="charcount"><i class="fas fa-font"></i> Character count</button>
        <button class="tool-btn" data-tool="sentencecount"><i class="fas fa-paragraph"></i> Sentences</button>
        <button class="tool-btn" data-tool="readability"><i class="fas fa-chart-line"></i> Readability</button>
        <button class="tool-btn" data-tool="cleaner"><i class="fas fa-broom"></i> Text cleaner</button>
        <button class="tool-btn" data-tool="case"><i class="fas fa-text-height"></i> Title case</button>
      </div>

      <!-- text input -->
      <div class="input-area">
        <textarea id="textInput" placeholder="Paste or type your text here … Try any tool above." spellcheck="true">The quick brown fox jumps over the lazy dog. This is a simple sentence for testing writing tools. Let's measure readability!</textarea>
      </div>

      <!-- results + action buttons -->
      <div class="result-panel" id="resultPanel">
        <div class="stat" id="primaryStat">
          <span class="stat-label"><i class="far fa-file-alt" style="margin-right: 5px;"></i> Words</span>
          <span class="stat-value" id="statNumber">0</span>
        </div>
        <div class="stat" id="secondaryStat">
          <span class="stat-label"><i class="far fa-clock"></i> Readability</span>
          <span class="stat-value small" id="statExtra">—</span>
        </div>
        <div class="action-buttons">
          <button class="action-btn" id="clearBtn"><i class="fas fa-undo-alt"></i> Clear</button>
          <button class="action-btn" id="copyBtn"><i class="far fa-copy"></i> Copy</button>
        </div>
      </div>

      <!-- info & how to -->
      <div class="info-section">
        <div>
          <h3><i class="fas fa-info-circle"></i> About this tool</h3>
          <p><strong>Instant writing metrics</strong> — no server, no API key. Everything runs in your browser. Select a tool above, edit text, and watch stats update immediately. Works offline, always free.</p>
          <p style="margin-top: 0.6rem;"><i class="fas fa-check-circle" style="color: #6c4cff; margin-right: 6px;"></i> Real‑time counts · character & word · sentence · readability (Flesch) · text cleaner & title case.</p>
        </div>
        <div>
          <h3><i class="fas fa-lightbulb"></i> How to use</h3>
          <ul>
            <li><i class="fas fa-circle"></i> Click any tool button (e.g., <span class="badge">Word counter</span>)</li>
            <li><i class="fas fa-circle"></i> Type or paste text into the box</li>
            <li><i class="fas fa-circle"></i> Results update <strong>instantly</strong></li>
            <li><i class="fas fa-circle"></i> Use <span class="badge">Clear</span> or <span class="badge">Copy</span> for quick actions</li>
            <li><i class="fas fa-circle"></i> Readability score: higher = easier to read</li>
          </ul>
        </div>
      </div>
    </div>
  </div>

  <script>
    (function() {
      // DOM elements
      const textArea = document.getElementById('textInput');
      const toolBtns = document.querySelectorAll('.tool-btn');
      const statNumber = document.getElementById('statNumber');
      const statExtra = document.getElementById('statExtra');
      const primaryStatLabel = document.querySelector('#primaryStat .stat-label');
      const secondaryStatLabel = document.querySelector('#secondaryStat .stat-label');
      const clearBtn = document.getElementById('clearBtn');
      const copyBtn = document.getElementById('copyBtn');

      // helper: get clean text (remove extra spaces for some counts)
      const getWordsArray = (text) => {
        return text.trim().split(/\s+/).filter(word => word.length > 0);
      };

      const getSentences = (text) => {
        // split by . ! ? and filter empty
        return text.split(/[.!?]+/).filter(s => s.trim().length > 0);
      };

      // readability: Flesch Reading Ease (approximate)
      const fleschReadability = (text) => {
        const words = getWordsArray(text);
        const wordCount = words.length;
        if (wordCount === 0) return 0;
        const sentences = getSentences(text);
        const sentenceCount = sentences.length || 1;
        // count syllables (rough: number of vowels per word)
        const syllableCount = words.reduce((acc, word) => {
          const clean = word.toLowerCase().replace(/[^a-z]/g, '');
          const vowels = (clean.match(/[aeiouy]/g) || []).length;
          return acc + Math.max(1, vowels);
        }, 0);
        // Flesch formula: 206.835 - 1.015*(words/sentences) - 84.6*(syllables/words)
        const score = 206.835 - 1.015 * (wordCount / sentenceCount) - 84.6 * (syllableCount / wordCount);
        return Math.min(100, Math.max(0, Math.round(score * 10) / 10));
      };

      // current active tool
      let activeTool = 'wordcount';

      // update UI based on tool
      function updateStats() {
        const text = textArea.value;
        const trimmed = text.trim();
        const wordArray = getWordsArray(text);
        const wordCount = wordArray.length;
        const charCount = text.length;
        const noSpaceCount = text.replace(/\s/g, '').length;
        const sentences = getSentences(text);
        const sentenceCount = sentences.length;
        const readabilityScore = fleschReadability(text);
        let primaryValue = 0;
        let secondaryValue = '';
        let primaryLabel = 'Words';
        let secondaryLabel = 'Readability';

        switch (activeTool) {
          case 'wordcount':
            primaryValue = wordCount;
            secondaryValue = charCount + ' chars';
            primaryLabel = 'Words';
            secondaryLabel = 'Characters';
            break;
          case 'charcount':
            primaryValue = charCount;
            secondaryValue = noSpaceCount + ' (no spaces)';
            primaryLabel = 'Characters';
            secondaryLabel = 'No spaces';
            break;
          case 'sentencecount':
            primaryValue = sentenceCount;
            secondaryValue = wordCount + ' words';
            primaryLabel = 'Sentences';
            secondaryLabel = 'Words';
            break;
          case 'readability':
            primaryValue = readabilityScore;
            let level = readabilityScore >= 60 ? 'easy' : readabilityScore >= 40 ? 'medium' : 'difficult';
            secondaryValue = level + ' · ' + wordCount + ' words';
            primaryLabel = 'Flesch score';
            secondaryLabel = 'Readability';
            break;
          case 'cleaner':
            // cleaned text: remove extra spaces, trim, collapse newlines?
            const cleaned = text.replace(/\s+/g, ' ').trim();
            primaryValue = cleaned.length;
            secondaryValue = 'cleaned · ' + (wordCount) + ' words';
            primaryLabel = 'Clean length';
            secondaryLabel = 'Result';
            // update textarea with cleaned version? we keep original, but we can show cleaned length
            break;
          case 'case':
            // title case: capitalize each word
            const titleCased = text.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
            primaryValue = titleCased.length;
            secondaryValue = 'title case';
            primaryLabel = 'Title length';
            secondaryLabel = 'Converted';
            break;
          default: break;
        }

        // update primary stat
        statNumber.textContent = primaryValue;
        primaryStatLabel.innerHTML = `<i class="far fa-file-alt" style="margin-right: 5px;"></i> ${primaryLabel}`;

        // update secondary stat
        if (activeTool === 'readability') {
          statExtra.textContent = secondaryValue;
          secondaryStatLabel.innerHTML = `<i class="fas fa-chart-line"></i> Score`;
        } else if (activeTool === 'cleaner' || activeTool === 'case') {
          statExtra.textContent = secondaryValue;
          secondaryStatLabel.innerHTML = `<i class="fas fa-${activeTool === 'cleaner' ? 'broom' : 'text-height'}"></i> ${secondaryLabel}`;
        } else {
          statExtra.textContent = secondaryValue;
          secondaryStatLabel.innerHTML = `<i class="far fa-clock"></i> ${secondaryLabel}`;
        }

        // for cleaner & case we can optionally update the text area to show transformed? but we keep original,
        // we just show stats. For cleaner we could also modify text, but we let user decide.
        // But we add a special indicator: if cleaner or case, we show transformation in a subtle way.
        if (activeTool === 'cleaner') {
          // we can also replace text if user wants? but we keep original, only show length.
          // we optionally show a preview in extra stat.
        }
        if (activeTool === 'case') {
          // title case preview not in textarea, but we can copy transformed.
        }
      }

      // set active tool and update UI
      function setActiveTool(toolId) {
        activeTool = toolId;
        // update button styles
        toolBtns.forEach(btn => {
          btn.classList.remove('active');
          if (btn.dataset.tool === toolId) {
            btn.classList.add('active');
          }
        });
        updateStats();
      }

      // event listeners for tool buttons
      toolBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
          const tool = this.dataset.tool;
          setActiveTool(tool);
        });
      });

      // text input update
      textArea.addEventListener('input', updateStats);

      // clear button
      clearBtn.addEventListener('click', function() {
        textArea.value = '';
        updateStats();
        textArea.focus();
      });

      // copy button (copy current text)
      copyBtn.addEventListener('click', function() {
        let contentToCopy = textArea.value;
        // if tool is cleaner, copy cleaned version
        if (activeTool === 'cleaner') {
          contentToCopy = textArea.value.replace(/\s+/g, ' ').trim();
        } else if (activeTool === 'case') {
          contentToCopy = textArea.value.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
        }
        navigator.clipboard.writeText(contentToCopy).then(() => {
          const original = copyBtn.innerHTML;
          copyBtn.innerHTML = '<i class="fas fa-check"></i> Copied!';
          setTimeout(() => { copyBtn.innerHTML = original; }, 1500);
        }).catch(() => {
          alert('Could not copy. Select text manually.');
        });
      });

      // initial update
      setActiveTool('wordcount');
    })();
  </script>

</body>
</html>
