    .result-box .placeholder {
      opacity: 0.4;
      font-weight: 300;
    }

    .copy-tip {
      font-size: 0.75rem;
      color: #2b5b8b;
      opacity: 0.6;
      margin-top: 0.25rem;
    }

    .inline-flex {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      align-items: center;
    }

    hr {
      margin: 0.5rem 0 1rem;
      border: 0;
      border-top: 1px solid rgba(0,0,0,0.03);
    }

    /* footer */
    .footer-note {
      margin-top: 3rem;
      text-align: center;
      font-size: 0.9rem;
      color: #4a5c72;
      opacity: 0.7;
      border-top: 1px solid rgba(43, 91, 139, 0.08);
      padding-top: 2rem;
    }

    .footer-note i {
      color: #2b5b8b;
    }

    /* responsive */
    @media (max-width: 600px) {
      .hero h1 { font-size: 2.2rem; }
      .tools-grid { grid-template-columns: 1fr; }
      .tool-card { padding: 1.5rem; }
    }
  </style>
</head>
<body>
<div class="app-wrapper">
  <div class="hero">
    <h1><i class="fas fa-chart-line" style="background: none; color: #1e3c5f; margin-right: 8px;"></i> marketing toolkit</h1>
    <p>No API keys · always functional · 6 essential tools for marketers</p>
    <div class="badge-usage">
      <i class="fas fa-lightbulb"></i> click “run” — instant results, copy & use
    </div>
  </div>

  <!-- grid of tools -->
  <div class="tools-grid" id="toolsGrid">
    <!-- 1. Keyword density -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-tag"></i><h3>Keyword density</h3></div>
      <div class="tool-desc">Paste text & get the most frequent keyword (single word).</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="keywordInput">Text snippet</label>
          <textarea id="keywordInput" placeholder="Enter your marketing copy or article...">content marketing is essential. marketing tools help marketers.</textarea>
        </div>
        <button class="action-btn" id="keywordBtn"><i class="fas fa-calculator"></i> find top keyword</button>
        <div class="result-box" id="keywordResult"><span class="placeholder">top keyword appears here</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click result to copy</div>
      </div>
    </div>

    <!-- 2. Hashtag generator -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-hashtag"></i><h3>Hashtag builder</h3></div>
      <div class="tool-desc">Enter a topic and generate 5 relevant hashtags (lowercase).</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="hashtagInput">Topic</label>
          <input id="hashtagInput" type="text" placeholder="e.g. marketing, seo, social" value="marketing">
        </div>
        <button class="action-btn" id="hashtagBtn"><i class="fas fa-hashtag"></i> generate tags</button>
        <div class="result-box" id="hashtagResult"><span class="placeholder">#tags will appear</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click to copy all</div>
      </div>
    </div>

    <!-- 3. Content character counter -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-text-width"></i><h3>Char counter</h3></div>
      <div class="tool-desc">Count characters & words (useful for ads & meta).</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="charInput">Your text</label>
          <textarea id="charInput" placeholder="Type or paste your ad copy, meta description...">Build marketing tools without API keys.</textarea>
        </div>
        <button class="action-btn" id="charBtn"><i class="fas fa-ruler"></i> count</button>
        <div class="result-box" id="charResult"><span class="placeholder">chars · words</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click to copy stats</div>
      </div>
    </div>

    <!-- 4. Case converter (title / sentence) -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-font"></i><h3>Case converter</h3></div>
      <div class="tool-desc">Convert text to Title Case or Sentence case.</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="caseInput">Text</label>
          <input id="caseInput" type="text" placeholder="your marketing headline" value="marketing tools for modern teams">
        </div>
        <div class="inline-flex">
          <button class="action-btn" id="titleCaseBtn" style="flex:1;"><i class="fas fa-heading"></i> Title</button>
          <button class="action-btn" id="sentenceCaseBtn" style="flex:1; background: #3a5f7a;"><i class="fas fa-paragraph"></i> Sentence</button>
        </div>
        <div class="result-box" id="caseResult"><span class="placeholder">converted text</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click to copy</div>
      </div>
    </div>

    <!-- 5. URL parameter builder -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-link"></i><h3>UTM builder</h3></div>
      <div class="tool-desc">Add UTM parameters to any URL (source, medium, campaign).</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="urlInput">Base URL</label>
          <input id="urlInput" type="text" placeholder="https://yoursite.com/page" value="https://example.com/landing">
        </div>
        <div style="display: flex; gap: 0.5rem; flex-wrap: wrap;">
          <input id="utmSource" placeholder="source" value="newsletter" style="flex:1; background: white; border:1px solid #dce5ef; border-radius:20px; padding:0.6rem 1rem;">
          <input id="utmMedium" placeholder="medium" value="email" style="flex:1; background: white; border:1px solid #dce5ef; border-radius:20px; padding:0.6rem 1rem;">
          <input id="utmCampaign" placeholder="campaign" value="june_launch" style="flex:1; background: white; border:1px solid #dce5ef; border-radius:20px; padding:0.6rem 1rem;">
        </div>
        <button class="action-btn" id="utmBtn"><i class="fas fa-link"></i> build UTM</button>
        <div class="result-box" id="utmResult"><span class="placeholder">url with parameters</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click to copy</div>
      </div>
    </div>

    <!-- 6. Social post formatter (line breaks) -->
    <div class="tool-card">
      <div class="tool-header"><i class="fas fa-share-alt"></i><h3>Post formatter</h3></div>
      <div class="tool-desc">Add line breaks every 2 sentences for better readability.</div>
      <div class="tool-body">
        <div class="input-group">
          <label for="postInput">Your social post</label>
          <textarea id="postInput" placeholder="Write your post...">Great marketing tools save time. They boost productivity. Use them daily. Reach your audience.</textarea>
        </div>
        <button class="action-btn" id="postBtn"><i class="fas fa-arrow-right"></i> format</button>
        <div class="result-box" id="postResult"><span class="placeholder">formatted post</span></div>
        <div class="copy-tip"><i class="far fa-copy"></i> click to copy</div>
      </div>
    </div>
  </div>

  <div class="footer-note">
    <i class="fas fa-bolt"></i> 100% client-side · no API keys · instant & private
  </div>
</div>

<script>
  (function() {
    // helper: copy to clipboard and show feedback
    function setupCopy(elementId) {
      const el = document.getElementById(elementId);
      if (!el) return;
      el.addEventListener('click', function(e) {
        const text = this.innerText.replace('click to copy', '').trim();
        if (!text || text === '' || text === 'placeholder' || text === 'top keyword appears here' || text === '#tags will appear' || text === 'chars · words' || text === 'converted text' || text === 'url with parameters' || text === 'formatted post') return;
        navigator.clipboard?.writeText(text).then(() => {
          const orig = this.style.background;
          this.style.background = '#d4e2f0';
          setTimeout(() => this.style.background = orig, 250);
        }).catch(() => {});
      });
    }

    // 1. Keyword density
    document.getElementById('keywordBtn').addEventListener('click', function() {
      const input = document.getElementById('keywordInput').value;
      const words = input.toLowerCase().match(/[a-z0-9]+/g) || [];
      if (words.length === 0) { document.getElementById('keywordResult').innerHTML = '⚠️ no words'; return; }
      const freq = {};
      words.forEach(w => freq[w] = (freq[w] || 0) + 1);
      let top = Object.keys(freq).reduce((a,b) => freq[a] > freq[b] ? a : b);
      document.getElementById('keywordResult').innerHTML = `<strong>“${top}”</strong> appears ${freq[top]} time${freq[top]>1?'s':''}`;
    });

    // 2. Hashtag builder
    document.getElementById('hashtagBtn').addEventListener('click', function() {
      const topic = document.getElementById('hashtagInput').value.trim() || 'marketing';
      const words = topic.split(/\s+/).filter(w => w.length > 1);
      let base = words.length ? words.join('') : 'marketing';
      const tags = [
        `#${base}`,
        `#${base}${Math.floor(Math.random()*100)}`,
        `#${base}tips`,
        `#${base}strategy`,
        `#${base}growth`
      ];
      document.getElementById('hashtagResult').innerHTML = tags.join(' ');
    });

    // 3. Char counter
    document.getElementById('charBtn').addEventListener('click', function() {
      const text = document.getElementById('charInput').value;
      const chars = text.length;
      const words = text.trim() === '' ? 0 : text.split(/\s+/).length;
      document.getElementById('charResult').innerHTML = `📊 ${chars} characters · ${words} words`;
    });

    // 4. Case converter
    function toTitleCase(str) {
      return str.toLowerCase().replace(/(?:^|\s)\S/g, c => c.toUpperCase());
    }
    document.getElementById('titleCaseBtn').addEventListener('click', function() {
      const val = document.getElementById('caseInput').value;
      document.getElementById('caseResult').innerHTML = toTitleCase(val);
    });
    document.getElementById('sentenceCaseBtn').addEventListener('click', function() {
      const val = document.getElementById('caseInput').value.toLowerCase();
      const sentences = val.split(/(\.\s+|\?|\!)/).filter(s => s.trim());
      let result = '';
      for (let i=0; i<sentences.length; i+=2) {
        const sent = (sentences[i] || '').trim();
        if (sent) result += sent.charAt(0).toUpperCase() + sent.slice(1) + (sentences[i+1] || '');
      }
      document.getElementById('caseResult').innerHTML = result || val;
    });

    // 5. UTM builder
    document.getElementById('utmBtn').addEventListener('click', function() {
      let base = document.getElementById('urlInput').value.trim() || 'https://example.com';
      if (!base.startsWith('http://') && !base.startsWith('https://')) base = 'https://' + base;
      const source = document.getElementById('utmSource').value.trim() || 'source';
      const medium = document.getElementById('utmMedium').value.trim() || 'medium';
      const campaign = document.getElementById('utmCampaign').value.trim() || 'campaign';
      const urlObj = new URL(base);
      urlObj.searchParams.set('utm_source', source);
      urlObj.searchParams.set('utm_medium', medium);
      urlObj.searchParams.set('utm_campaign', campaign);
      document.getElementById('utmResult').innerHTML = urlObj.toString();
    });

    // 6. Social post formatter (2 sentences per line)
    document.getElementById('postBtn').addEventListener('click', function() {
      const input = document.getElementById('postInput').value;
      const sentences = input.match(/[^.!?]*[.!?]+/g) || [input];
      let formatted = '';
      for (let i=0; i<sentences.length; i+=2) {
        const group = sentences.slice(i, i+2).join(' ').trim();
        if (group) formatted += group + '\n';
      }
      document.getElementById('postResult').innerHTML = formatted.trim() || input;
    });

    // copy listeners for result boxes
    setupCopy('keywordResult');
    setupCopy('hashtagResult');
    setupCopy('charResult');
    setupCopy('caseResult');
    setupCopy('utmResult');
    setupCopy('postResult');

    // quick fill examples (UX)
    // set initial values for demo
    document.querySelector('#keywordInput').value = 'content marketing is essential. marketing tools help marketers.';
  })();
</script>
</body>
</html>
