</head>
<body>
<div class="glass-card">
    <div class="tool-header">
        <h1>
            ✦ Social Tools
            <span>free</span>
        </h1>
        <div class="info-badge">
            ⚡ 100% client-side · no API key
        </div>
    </div>

    <!-- description + how-to -->
    <div class="tool-description">
        <p>
            <span>📌 <strong>All-in-one toolkit</strong> for social media creators.</span>
            <span class="howto">⏵ type, click, copy — it just works</span>
            <span style="font-size:0.9rem; opacity:0.8;">Character counter · hashtag generator · emoji picker · username styler · case converter</span>
        </p>
    </div>

    <!-- tools grid -->
    <div class="tools-grid">

        <!-- 1. Character counter -->
        <div class="tool-item">
            <h3><i>🔤</i> Char counter</h3>
            <p>Count characters & words in real-time.</p>
            <textarea id="charInput" placeholder="Write your caption here..." rows="2"></textarea>
            <div class="result-box" id="charResult">
                <span>📝 0 characters · 0 words</span>
            </div>
        </div>

        <!-- 2. Hashtag generator -->
        <div class="tool-item">
            <h3><i>#️⃣</i> Hashtag generator</h3>
            <p>Type a topic, get 5 popular hashtags.</p>
            <input type="text" id="hashtagInput" placeholder="e.g. productivity" value="socialmedia">
            <div class="result-box" id="hashtagResult">
                <span class="tag">#social</span> <span class="tag">#media</span> <span class="tag">#tips</span>
            </div>
        </div>

        <!-- 3. Emoji picker (click to copy) -->
        <div class="tool-item">
            <h3><i>😊</i> Emoji picker</h3>
            <p>Click any emoji to copy to clipboard.</p>
            <div class="emoji-grid" id="emojiGrid">
                <span>🔥</span><span>✨</span><span>💯</span><span>🚀</span><span>❤️</span>
                <span>😍</span><span>😂</span><span>🤩</span><span>👍</span><span>🎉</span>
                <span>💡</span><span>📸</span><span>👀</span><span>⭐</span><span>🌈</span>
                <span>💎</span><span>🎯</span><span>💪</span><span>🤝</span><span>🔥</span>
            </div>
            <div class="result-box" id="emojiResult">📋 click emoji → copied</div>
        </div>

        <!-- 4. Username styler -->
        <div class="tool-item">
            <h3><i>✏️</i> Username styler</h3>
            <p>Add fancy symbols around your name.</p>
            <input type="text" id="usernameInput" placeholder="your name" value="Alex">
            <div class="result-box" id="usernameResult">✨ Alex ✨</div>
        </div>

        <!-- 5. Case converter -->
        <div class="tool-item">
            <h3><i>🔠</i> Case converter</h3>
            <p>Transform text to UPPER, lower, Title.</p>
            <input type="text" id="caseInput" placeholder="type here" value="social tools">
            <div style="display: flex; gap: 0.4rem; flex-wrap: wrap; margin-top: 0.5rem;">
                <button class="btn-copy" data-case="upper">UPPER</button>
                <button class="btn-copy" data-case="lower">lower</button>
                <button class="btn-copy" data-case="title">Title</button>
