    <div class="footer-note">⚡  fast · privacy-first · all logic runs in your browser</div>
</div>

<script>
    (function() {
        "use strict";

        // ----- char counter -----
        const charInput = document.getElementById('charInput');
        const charResult = document.getElementById('charResult');

        function updateCharCount() {
            const text = charInput.value || '';
            const charCount = text.length;
            const wordCount = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;
            charResult.innerHTML = `<span>📝 ${charCount} characters · ${wordCount} words</span>`;
        }
        charInput.addEventListener('input', updateCharCount);
        updateCharCount();

        // ----- hashtag generator -----
        const hashtagInput = document.getElementById('hashtagInput');
        const hashtagResult = document.getElementById('hashtagResult');

        function generateHashtags(topic) {
            const clean = topic.trim().replace(/\s+/g, '');
            if (!clean) return ['#social', '#media', '#tips'];
            const base = clean.toLowerCase();
            const variants = [
                `#${base}`,
                `#${base}life`,
                `#${base}goals`,
                `#${base}community`,
                `#${base}love`
            ];
            return variants;
        }

        function renderHashtags() {
            const topic = hashtagInput.value || 'social';
            const tags = generateHashtags(topic);
            hashtagResult.innerHTML = tags.map(t => `<span class="tag">${t}</span>`).join(' ');
        }
        hashtagInput.addEventListener('input', renderHashtags);
        renderHashtags();

        // ----- emoji picker (copy) -----
        const emojiGrid = document.getElementById('emojiGrid');
        const emojiResult = document.getElementById('emojiResult');

        emojiGrid.addEventListener('click', function(e) {
            const target = e.target.closest('span');
            if (!target) return;
            const emoji = target.textContent;
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(emoji).then(() => {
                    emojiResult.innerHTML = `✅ "${emoji}" copied to clipboard!`;
                    setTimeout(() => {
                        emojiResult.innerHTML = `📋 click emoji → copied`;
                    }, 2500);
                }).catch(() => {
                    fallbackCopy(emoji);
                });
            } else {
                fallbackCopy(emoji);
            }
        });

        function fallbackCopy(text) {
            const textarea = document.createElement('textarea');
            textarea.value = text;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();
            try {
                document.execCommand('copy');
                emojiResult.innerHTML = `✅ "${text}" copied!`;
                setTimeout(() => {
                    emojiResult.innerHTML = `📋 click emoji → copied`;
                }, 2500);
            } catch (e) {
                emojiResult.innerHTML = `⚠️ could not copy, select manually.`;
            }
            document.body.removeChild(textarea);
        }

        // ----- username styler -----
        const usernameInput = document.getElementById('usernameInput');
        const usernameResult = document.getElementById('usernameResult');

        function styleUsername() {
            const name = usernameInput.value.trim() || 'Alex';
            const styled = `✨ ${name} ✨`;
            usernameResult.textContent = styled;
        }
        usernameInput.addEventListener('input', styleUsername);
        styleUsername();

        // ----- case converter -----
        const caseInput = document.getElementById('caseInput');
        const caseResult = document.getElementById('caseResult');
        const caseButtons = document.querySelectorAll('[data-case]');

        function convertCase(type) {
            const text = caseInput.value || 'social tools';
            let result = '';
            if (type === 'upper') result = text.toUpperCase();
            else if (type === 'lower') result = text.toLowerCase();
            else if (type === 'title') {
                result = text.toLowerCase().replace(/(^|\s)\S/g, (ch) => ch.toUpperCase());
            }
            caseResult.textContent = result;
        }

        caseButtons.forEach(btn => {
            btn.addEventListener('click', function(e) {
                const type = this.getAttribute('data-case');
                convertCase(type);
            });
        });

        // initial case conversion (upper)
        caseInput.addEventListener('input', function() {
            // default: show upper
            convertCase('upper');
        });
        // set initial
        convertCase('upper');

        // ----- copy result for hashtag & username (nice to have) but not required.
        // bonus: click on result box for hashtag copy? we keep simple.

        // Also clicking on result hashtags copies if user wants? we add extra.
        hashtagResult.addEventListener('click', function(e) {
            const tag = e.target.closest('.tag');
            if (!tag) return;
            const text = tag.textContent;
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    hashtagResult.innerHTML += ` <span style="background:#d4e2f5; border-radius:20px; padding:0 0.5rem;">✅ copied</span>`;
                    setTimeout(() => renderHashtags(), 1500);
                }).catch(() => {});
            } else {
                fallbackCopy(text);
            }
        });

        // Username click to copy
        usernameResult.addEventListener('click', function() {
            const text = this.textContent;
            if (!text) return;
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    usernameResult.style.background = 'rgba(42,75,124,0.1)';
                    setTimeout(() => usernameResult.style.background = '', 600);
                }).catch(() => {});
            } else {
                fallbackCopy(text);
            }
        });

        // case result click to copy
        caseResult.addEventListener('click', function() {
            const text = this.textContent;
            if (!text) return;
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(text).then(() => {
                    caseResult.style.background = 'rgba(42,75,124,0.1)';
                    setTimeout(() => caseResult.style.background = '', 600);
                }).catch(() => {});
            } else {
                fallbackCopy(text);
            }
        });

        console.log('✨ Social Tools loaded — 100% functional, no API keys needed.');
    })();
</script>
</body>
</html>
