          <button class="btn btn-secondary" id="clearJsonBtn"><i class="fas fa-undo-alt"></i> Clear</button>
        </div>
        <div id="jsonOutput" class="output-box">Formatted JSON will appear here</div>
      </div>
    </div>

    <!-- CARD 2: Text Case Converter -->
    <div class="card">
      <div class="card-title"><i class="fas fa-font"></i> Text Converter</div>
      <div class="card-desc"><i class="fas fa-arrow-right"></i> UPPER, lower, Title &amp; more</div>
      <div class="tool-area">
        <input type="text" id="textInput" value="transform this text" placeholder="write anything...">
        <div class="btn-group">
          <button class="btn btn-primary" id="toUpperBtn"><i class="fas fa-arrow-up"></i> UPPER</button>
          <button class="btn btn-secondary" id="toLowerBtn"><i class="fas fa-arrow-down"></i> lower</button>
          <button class="btn btn-secondary" id="toTitleBtn"><i class="fas fa-heading"></i> Title</button>
          <button class="btn btn-secondary" id="toCamelBtn"><i class="fas fa-camel"></i> camel</button>
        </div>
        <div id="textOutput" class="output-box">TRANSFORM THIS TEXT</div>
      </div>
