          <input type="color" id="colorPicker" value="#2563eb">
          <span class="color-hex" id="colorHexDisplay">#2563eb</span>
          <button class="btn btn-secondary" id="copyColorBtn"><i class="fas fa-copy"></i> Copy</button>
        </div>
        <div style="margin-top: 1rem; display: flex; gap: 0.6rem; flex-wrap: wrap;">
          <button class="btn btn-secondary" id="randomColorBtn"><i class="fas fa-dice"></i> Random</button>
          <button class="btn btn-secondary" id="resetColorBtn"><i class="fas fa-undo"></i> Reset</button>
        </div>
        <div id="colorPreview" style="height: 40px; border-radius: 60px; margin-top: 0.8rem; background: #2563eb; border: 1px solid #d1d9e6;"></div>
      </div>
    </div>

    <!-- CARD 4: Base64 Encoder/Decoder -->
    <div class="card">
      <div class="card-title"><i class="fas fa-lock"></i> Base64</div>
      <div class="card-desc"><i class="fas fa-exchange-alt"></i> Encode / Decode text</div>
      <div class="tool-area">
        <textarea id="base64Input" rows="2" placeholder="text or base64">Hello Dev!</textarea>
        <div class="btn-group">
          <button class="btn btn-primary" id="encodeBase64Btn"><i class="fas fa-arrow-right"></i> Encode</button>
          <button class="btn btn-secondary" id="decodeBase64Btn"><i class="fas fa-arrow-left"></i> Decode</button>
          <button class="btn btn-secondary" id="clearBase64Btn"><i class="fas fa-eraser"></i> Clear</button>
        </div>
        <div id="base64Output" class="output-box">SGVsbG8gRGV2IQ==</div>
