<script>
  (function() {
    "use strict";

    // ---------- JSON ----------
    const jsonInput = document.getElementById('jsonInput');
    const jsonOutput = document.getElementById('jsonOutput');

    function formatJson() {
      try {
        const parsed = JSON.parse(jsonInput.value);
        jsonOutput.textContent = JSON.stringify(parsed, null, 2);
      } catch (e) {
        jsonOutput.textContent = '⚠️ Invalid JSON: ' + e.message;
      }
    }

    function minifyJson() {
      try {
        const parsed = JSON.parse(jsonInput.value);
        jsonOutput.textContent = JSON.stringify(parsed);
      } catch (e) {
        jsonOutput.textContent = '⚠️ Invalid JSON: ' + e.message;
      }
    }

    document.getElementById('formatJsonBtn').addEventListener('click', formatJson);
    document.getElementById('minifyJsonBtn').addEventListener('click', minifyJson);
    document.getElementById('clearJsonBtn').addEventListener('click', function() {
      jsonInput.value = '';
      jsonOutput.textContent = 'cleared';
    });

    // ---------- TEXT CASE ----------
    const textInput = document.getElementById('textInput');
    const textOutput = document.getElementById('textOutput');

    function setTextTransform(fn) {
      const val = textInput.value;
      if (val.trim() === '') {
        textOutput.textContent = '(empty)';
        return;
      }
      textOutput.textContent = fn(val);
    }

    document.getElementById('toUpperBtn').addEventListener('click', function() {
      setTextTransform(str => str.toUpperCase());
    });
    document.getElementById('toLowerBtn').addEventListener('click', function() {
      setTextTransform(str => str.toLowerCase());
    });
    document.getElementById('toTitleBtn').addEventListener('click', function() {
      setTextTransform(str => str.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()));
    });
    document.getElementById('toCamelBtn').addEventListener('click', function() {
      setTextTransform(str => str.replace(/(?:^\w|[A-Z]|\b\w|\s+)/g, (match, index) => 
        index === 0 ? match.toLowerCase() : match.toUpperCase()
      ).replace(/\s+/g, ''));
    });

    // ---------- COLOR PICKER ----------
    const colorPicker = document.getElementById('colorPicker');
    const colorHexDisplay = document.getElementById('colorHexDisplay');
    const colorPreview = document.getElementById('colorPreview');

    function updateColorFromPicker() {
      const col = colorPicker.value;
      colorHexDisplay.textContent = col;
      colorPreview.style.background = col;
    }

    colorPicker.addEventListener('input', updateColorFromPicker);
    document.getElementById('randomColorBtn').addEventListener('click', function() {
      const randomHex = '#' + Math.floor(Math.random()*16777215).toString(16).padStart(6, '0');
      colorPicker.value = randomHex;
      updateColorFromPicker();
    });
    document.getElementById('resetColorBtn').addEventListener('click', function() {
      colorPicker.value = '#2563eb';
      updateColorFromPicker();
    });
    document.getElementById('copyColorBtn').addEventListener('click', function() {
      const hex = colorHexDisplay.textContent;
      navigator.clipboard?.writeText(hex).then(() => {
        const orig = colorHexDisplay.textContent;
        colorHexDisplay.textContent = '✓ copied!';
        setTimeout(() => colorHexDisplay.textContent = orig, 1000);
      }).catch(() => {
        alert('Copy: ' + hex);
      });
    });
    updateColorFromPicker(); // init

    // ---------- BASE64 ----------
    const base64Input = document.getElementById('base64Input');
    const base64Output = document.getElementById('base64Output');

    document.getElementById('encodeBase64Btn').addEventListener('click', function() {
      try {
        const text = base64Input.value;
        if (!text) { base64Output.textContent = '(empty)'; return; }
        base64Output.textContent = btoa(unescape(encodeURIComponent(text)));
      } catch (e) {
        base64Output.textContent = '⚠️ Encoding error: ' + e.message;
      }
    });

    document.getElementById('decodeBase64Btn').addEventListener('click', function() {
      try {
        const encoded = base64Input.value;
        if (!encoded) { base64Output.textContent = '(empty)'; return; }
        const decoded = decodeURIComponent(escape(atob(encoded)));
        base64Output.textContent = decoded;
      } catch (e) {
        base64Output.textContent = '⚠️ Invalid Base64: ' + e.message;
      }
    });

    document.getElementById('clearBase64Btn').addEventListener('click', function() {
      base64Input.value = '';
      base64Output.textContent = 'cleared';
    });

    // seed demo values on page load (keep example)
    window.addEventListener('load', function() {
      formatJson(); // initial format
      // text output initial
      textOutput.textContent = textInput.value.toUpperCase();
      // base64 initial
      base64Output.textContent = btoa(unescape(encodeURIComponent(base64Input.value)));
    });

  })();
</script>
</body>
</html>
