<body>
 <div class="card" role="main">
 <!-- header -->
 <div class="header">
 <i class="fas fa-wand-magic-sparkles"></i>
 <h1>YT Title Forge</h1>
 </div>
 <div class="subhead">
 <i class="fas fa-bolt" style="margin-right: 6px; color: #3b4fef;"></i> 5 fresh titles · 8 styles · zero API
 </div>

 <!-- brief info & usage -->
 <div class="info-box">
 <i class="fas fa-circle-info"></i>
 <div class="info-text">
 <strong>How to use:</strong> Type your video topic, pick a style, click <span>Generate</span>. 
 Get 5 titles instantly. Copy any title with the <i class="far fa-copy" style="margin:0 2px;"></i> icon. 
 Works offline, always free.
 </div>
 </div>

 <!-- input area -->
 <div class="input-group">
 <div class="input-wrapper">
 <i class="fas fa-pen"></i>
 <input type="text" id="topicInput" placeholder="e.g. 'indie game dev vlog'" value="coding in the rain">
 </div>
 <div class="style-select">
 <i class="fas fa-sliders-h"></i>
 <select id="styleSelect">
 <option value="clickbait">🔥 Clickbait</option>
 <option value="howto" selected>📘 How-to</option>
 <option value="list">📋 List / Top</option>
 <option value="story">📖 Storytelling</option>
 <option value="question">❓ Question</option>
 <option value="epic">⚡ Epic / Cinematic</option>
 <option value="funny">😂 Funny / Meme</option>
 <option value="minimal">✨ Minimal / Clean</option>
 </select>
 </div>
 <button class="generate-btn" id="generateBtn">
 <i class="fas fa-arrow-right"></i> Generate
 </button>
 </div>

 <!-- titles output -->
 <div class="titles-container" id="titlesContainer">
 <!-- dynamically filled -->
 <div class="empty-state" id="emptyState">
 <i class="fas fa-film"></i>
 <div style="font-weight: 450;">Your titles will appear here</div>
 <div style="font-size:0.8rem; margin-top:6px;">try “coding in the rain” · style: How-to</div>
 </div>
 </div>

 <!-- footer / extra seo hint -->
 <div class="footer-note">
 <i class="fas fa-shield-alt"></i>
 <span>100% functional</span>
 <i class="fas fa-robot" style="margin-left:auto;"></i>
 <span style="background:transparent; padding-left:0;">⚡ no API key</span>
 </div>
 </div>

 <script>
 (function() {
 // -------------------- title generator engine --------------------
 // 8 style banks – each returns array of 5 title templates (with {topic})
 const styleBanks = {
 clickbait: [
 "You Won't BELIEVE This {topic} Hack! 🔥",
 "This {topic} Changed My Life Forever",
 "The SHOCKING Truth About {topic}",
 "99% of People Get {topic} WRONG",
 "I Tried {topic} for 30 Days – Here's What Happened"
 ],
 howto: [
 "How to Master {topic} in 5 Minutes",
 "The Ultimate Guide to {topic} (2026)",
 "How I Learned {topic} (and You Can Too)",
 "Step-by-Step {topic} for Beginners",
 "How to Start {topic} – No Experience Needed"
 ],
 list: [
 "Top 5 {topic} Tips You Need to Know",
 "7 {topic} Secrets That Actually Work",
 "The Best {topic} Strategies Ranked",
 "5 {topic} Mistakes to Avoid at All Costs",
 "10 {topic} Ideas That Will Blow Your Mind"
 ],
 story: [
 "My Journey with {topic} – From Zero to Hero",
 "The Day {topic} Changed Everything",
 "Why I Quit {topic} (and Why I Came Back)",
 "The Untold Story of {topic}",
 "How {topic} Saved My Creative Career"
 ],
 question: [
 "Is {topic} Really Worth It? (Honest Answer)",
 "Why Is {topic} So Popular Right Now?",
 "Can {topic} Actually Make You Money?",
 "What Nobody Tells You About {topic}",
 "How Much Does {topic} Really Cost?"
 ],
 epic: [
 "The EPIC {topic} Journey Begins Now",
 "Unleash Your {topic} Potential (Full Power)",
 "The Ultimate {topic} Experience – 4K",
 "Master {topic} Like a Legend",
 "Epic {topic} Moments That Define Greatness"
 ],
 funny: [
 "I Tried {topic} and It Was a Disaster 😂",
 "When {topic} Goes WRONG (Priceless)",
 "My {topic} Fail – You'll Laugh Out Loud",
 "The Most Ridiculous {topic} Ever",
 "Why I'm Terrible at {topic} (and proud)"
 ],
 minimal: [
 "{topic} · A Fresh Perspective",
 "The Art of {topic} · Less is More",
 "{topic} in 2026 · Clean & Clear",
 "Pure {topic} · No Fluff, Just Value",
 "{topic} · The Minimalist Approach"
 ]
 };

 // DOM elements
 const topicInput = document.getElementById('topicInput');
 const styleSelect = document.getElementById('styleSelect');
 const generateBtn = document.getElementById('generateBtn');
 const titlesContainer = document.getElementById('titlesContainer');

 // helper: generate 5 titles for a given topic & style key
 function generateTitles(topic, styleKey) {
 const templates = styleBanks[styleKey] || styleBanks.howto;
 // if topic empty, use fallback
 const cleanTopic = topic.trim() || "your next video";
 // capitalize first letter of each word? keep as is, but replace {topic}
 return templates.map(template => template.replace(/{topic}/g, cleanTopic));
 }

 // render titles in container
 function renderTitles(titlesArray) {
 // clear container, remove empty state
 titlesContainer.innerHTML = '';

 if (!titlesArray || titlesArray.length === 0) {
 // show empty state
 const empty = document.createElement('div');
 empty.className = 'empty-state';
 empty.id = 'emptyState';
 empty.innerHTML = `
 <i class="fas fa-film"></i>
 <div style="font-weight: 450;">Your titles will appear here</div>
 <div style="font-size:0.8rem; margin-top:6px;">try “coding in the rain” · style: How-to</div>
 `;
 titlesContainer.appendChild(empty);
 return;
 }

 // build title items
 titlesArray.forEach((title, index) => {
 const item = document.createElement('div');
 item.className = 'title-item';

 const indexSpan = document.createElement('span');
 indexSpan.className = 'title-index';
 indexSpan.textContent = `#${index + 1}`;

 const textSpan = document.createElement('span');
 textSpan.className = 'title-text';
 textSpan.textContent = title;

 const copyBtn = document.createElement('button');
 copyBtn.className = 'title-copy';
 copyBtn.setAttribute('aria-label', 'Copy title');
 copyBtn.innerHTML = '<i class="far fa-copy"></i>';
 // copy logic
 copyBtn.addEventListener('click', function(e) {
 e.stopPropagation();
 const titleText = textSpan.textContent;
 navigator.clipboard?.writeText(titleText).then(() => {
 // brief feedback
 const feedback = document.createElement('span');
 feedback.className = 'copy-feedback';
 feedback.textContent = '✓ copied';
 // append after copy btn, remove after 1.2s
 copyBtn.appendChild(feedback);
 setTimeout(() => {
 if (feedback.parentNode) feedback.remove();
 }, 1200);
 }).catch(() => {
 // fallback
 const textArea = document.createElement('textarea');
 textArea.value = titleText;
 document.body.appendChild(textArea);
 textArea.select();
 document.execCommand('copy');
 textArea.remove();
 const feedback = document.createElement('span');
 feedback.className = 'copy-feedback';
 feedback.textContent = '✓ copied';
 copyBtn.appendChild(feedback);
 setTimeout(() => {
 if (feedback.parentNode) feedback.remove();
 }, 1200);
 });
 });

 item.appendChild(indexSpan);
 item.appendChild(textSpan);
 item.appendChild(copyBtn);
 titlesContainer.appendChild(item);
 });
 }

 // main generation function
 function handleGenerate() {
 const topic = topicInput.value || "your next video";
 const style = styleSelect.value;
 const titles = generateTitles(topic, style);
 renderTitles(titles);
 }

 // event listeners
 generateBtn.addEventListener('click', handleGenerate);

 // press Enter in topic input to trigger generate
 topicInput.addEventListener('keydown', (e) => {
 if (e.key === 'Enter') {
 e.preventDefault();
 generateBtn.click();
 }
 });

 // initial load: generate default (topic "coding in the rain", style howto)
 // but we want to show something on load, so we call it
 window.addEventListener('DOMContentLoaded', function() {
 // set default topic from input value
 handleGenerate();
 });

 // also when style changes? optional: but we keep explicit generate
 // we also allow style change and generate via button, but we can add auto? 
 // better to keep it explicit, but if user wants, they click generate.

 // extra: if user clears input and press generate, fallback works
 })();
 </script>
</body>
