 font-size: 0.95rem;
 width: 100%;
 background: transparent;
 font-weight: 500;
 color: #0b1a33;
 outline: none;
 cursor: pointer;
 appearance: none;
 -webkit-appearance: none;
 background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="%235a6e8a" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>');
 background-repeat: no-repeat;
 background-position: right 0.2rem center;
 background-size: 14px;
 }

 .style-select select option {
 background: white;
 color: #0b1a33;
 }

 .generate-btn {
