<body>
<div class="main-wrapper">

  <!-- header -->
  <header class="tool-header">
    <h1><i class="fas fa-cubes"></i> toolhub</h1>
    <p><i class="fas fa-bolt" style="margin-right: 6px;"></i> 5 essential tools · instant results</p>
  </header>

  <!-- info & howto -->
  <div class="info-card">
    <div class="howto">
      <i class="fas fa-compass"></i>
      <span><strong>How to use:</strong> pick a tool, enter your data, click the action — results appear instantly.</span>
    </div>
    <div class="badge"><i class="fas fa-star" style="margin-right: 6px;"></i> 100% client‑side</div>
  </div>

  <!-- tool grid: 5 tools -->
  <div class="tool-grid" id="toolGrid">
    <!-- 1. Color converter (hex → rgb) -->
    <div class="tool-card" data-tool="color">
      <h3><i class="fas fa-palette"></i> Color converter</h3>
      <div class="tool-body">
        <label><i class="far fa-circle" style="color:#6c4ce0;"></i> Hex color</label>
        <input type="text" id="hexInput" value="#6c4ce0" placeholder="#hex">
        <div class="tool-actions">
          <button class="btn btn-primary" id="convertColorBtn"><i class="fas fa-arrow-right"></i> to RGB</button>
          <button class="btn btn-outline" id="randomColorBtn"><i class="fas fa-dice"></i> random</button>
        </div>
        <div class="result-box" id="colorResult"><i class="fas fa-tint"></i> rgb(108, 76, 224)</div>
      </div>
    </div>

    <!-- 2. Text case converter -->
    <div class="tool-card" data-tool="case">
      <h3><i class="fas fa-font"></i> Case converter</h3>
      <div class="tool-body">
        <label><i class="far fa-keyboard"></i> Your text</label>
        <input type="text" id="caseInput" value="hello world!">
        <div class="tool-actions">
          <button class="btn btn-primary" id="toUpperBtn"><i class="fas fa-arrow-up"></i> UPPER</button>
          <button class="btn btn-primary" id="toLowerBtn"><i class="fas fa-arrow-down"></i> lower</button>
          <button class="btn btn-outline" id="toTitleBtn"><i class="fas fa-heading"></i> Title</button>
        </div>
        <div class="result-box" id="caseResult"><i class="fas fa-magic"></i> HELLO WORLD!</div>
      </div>
    </div>

    <!-- 3. Word & character counter (FIXED) -->
    <div class="tool-card" data-tool="counter">
      <h3><i class="fas fa-calculator"></i> Text counter</h3>
      <div class="tool-body">
        <label><i class="far fa-file-alt"></i> Paste / type</label>
        <textarea id="counterText" rows="2">Write something cool ✨</textarea>
        <div class="tool-actions">
          <button class="btn btn-primary" id="countBtn"><i class="fas fa-chart-simple"></i> Count</button>
          <button class="btn btn-outline" id="clearCounterBtn"><i class="fas fa-undo-alt"></i> clear</button>
        </div>
        <div class="result-box" id="counterResult"><i class="fas fa-words"></i> words: 3 · chars: 22</div>
      </div>
    </div>

    <!-- 4. Random generator (number) -->
    <div class="tool-card" data-tool="random">
      <h3><i class="fas fa-dice"></i> Random number</h3>
      <div class="tool-body">
        <label><i class="fas fa-arrows-left-right"></i> Range</label>
        <div style="display: flex; gap: 0.6rem;">
          <input type="number" id="randMin" value="1" style="width: 50%;">
          <input type="number" id="randMax" value="100" style="width: 50%;">
        </div>
        <div class="tool-actions">
          <button class="btn btn-primary" id="generateRandomBtn"><i class="fas fa-shuffle"></i> Generate</button>
        </div>
        <div class="result-box" id="randomResult"><i class="fas fa-hashtag"></i> 42</div>
      </div>
    </div>

    <!-- 5. Length converter (cm ↔ inch) -->
    <div class="tool-card" data-tool="length">
      <h3><i class="fas fa-ruler"></i> Length converter</h3>
      <div class="tool-body">
        <label><i class="fas fa-arrow-right-arrow-left"></i> value</label>
        <input type="number" id="lengthInput" value="10" step="any">
        <div class="tool-actions">
          <button class="btn btn-primary" id="toInchBtn"><i class="fas fa-arrow-right"></i> cm → inch</button>
          <button class="btn btn-primary" id="toCmBtn"><i class="fas fa-arrow-left"></i> inch → cm</button>
        </div>
        <div class="result-box" id="lengthResult"><i class="fas fa-arrows"></i> 10 cm = 3.94 inch</div>
      </div>
    </div>
  </div>

  <div class="footer-note">
    <i class="fas fa-shield-alt"></i> all tools run in your browser · no data sent · modern & fancy
  </div>
</div>

<script>
  (function() {
    // ---------- 1. COLOR CONVERTER ----------
    const hexInput = document.getElementById('hexInput');
    const colorResult = document.getElementById('colorResult');
    const convertColorBtn = document.getElementById('convertColorBtn');
    const randomColorBtn = document.getElementById('randomColorBtn');

    function hexToRgb(hex) {
      let clean = hex.trim();
      if (clean.startsWith('#')) clean = clean.slice(1);
      if (clean.length === 3) clean = clean.split('').map(c => c+c).join('');
      if (clean.length !== 6) return null;
      const r = parseInt(clean.substring(0,2), 16);
      const g = parseInt(clean.substring(2,4), 16);
      const b = parseInt(clean.substring(4,6), 16);
      if (isNaN(r)||isNaN(g)||isNaN(b)) return null;
      return { r, g, b };
    }

    function updateColorResult() {
      const val = hexInput.value.trim();
      const rgb = hexToRgb(val);
      if (rgb) {
        colorResult.innerHTML = `<i class="fas fa-tint"></i> rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
      } else {
        colorResult.innerHTML = `<i class="fas fa-exclamation-triangle" style="color:#d46b6b;"></i> invalid hex (use #rrggbb)`;
      }
    }

    convertColorBtn.addEventListener('click', updateColorResult);
    randomColorBtn.addEventListener('click', function() {
      const randomHex = '#' + Math.floor(Math.random()*16777215).toString(16).padStart(6, '0');
      hexInput.value = randomHex;
      updateColorResult();
    });
    hexInput.addEventListener('input', updateColorResult);
    updateColorResult();

    // ---------- 2. CASE CONVERTER ----------
    const caseInput = document.getElementById('caseInput');
    const caseResult = document.getElementById('caseResult');

    function setCase(transformFn) {
      const val = caseInput.value;
      caseResult.innerHTML = `<i class="fas fa-magic"></i> ${transformFn(val)}`;
    }

    document.getElementById('toUpperBtn').addEventListener('click', () => setCase(v => v.toUpperCase()));
    document.getElementById('toLowerBtn').addEventListener('click', () => setCase(v => v.toLowerCase()));
    document.getElementById('toTitleBtn').addEventListener('click', () => setCase(v => v.replace(/\w\S*/g, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())));
    caseInput.addEventListener('input', () => setCase(v => v));

    // ---------- 3. COUNTER (FIXED) ----------
    const counterText = document.getElementById('counterText');
    const counterResult = document.getElementById('counterResult');
    const countBtn = document.getElementById('countBtn');
    const clearCounterBtn = document.getElementById('clearCounterBtn');

    function updateCounter() {
      const text = counterText.value;
      // Count words: split by whitespace and filter out empty strings
      const words = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;
      const chars = text.length;
      counterResult.innerHTML = `<i class="fas fa-words"></i> words: ${words} · chars: ${chars}`;
    }

    countBtn.addEventListener('click', updateCounter);
    clearCounterBtn.addEventListener('click', function() {
      counterText.value = '';
      updateCounter();
    });
    counterText.addEventListener('input', updateCounter);
    // Initial count
    updateCounter();

    // ---------- 4. RANDOM GENERATOR ----------
    const randMin = document.getElementById('randMin');
    const randMax = document.getElementById('randMax');
    const randomResult = document.getElementById('randomResult');
    const generateRandomBtn = document.getElementById('generateRandomBtn');

    function generateRandom() {
      let min = parseInt(randMin.value) || 0;
      let max = parseInt(randMax.value) || 100;
      if (min > max) [min, max] = [max, min];
      const rand = Math.floor(Math.random() * (max - min + 1)) + min;
      randomResult.innerHTML = `<i class="fas fa-hashtag"></i> ${rand}`;
    }

    generateRandomBtn.addEventListener('click', generateRandom);
    generateRandom();

    // ---------- 5. LENGTH CONVERTER ----------
    const lengthInput = document.getElementById('lengthInput');
    const lengthResult = document.getElementById('lengthResult');

    function convertLength(unit) {
      const val = parseFloat(lengthInput.value);
      if (isNaN(val)) {
        lengthResult.innerHTML = `<i class="fas fa-exclamation-triangle" style="color:#d46b6b;"></i> enter a valid number`;
        return;
      }
      if (unit === 'cmToInch') {
        const inch = (val * 0.393701).toFixed(3);
        lengthResult.innerHTML = `<i class="fas fa-arrows"></i> ${val} cm = ${inch} inch`;
      } else {
        const cm = (val / 0.393701).toFixed(3);
        lengthResult.innerHTML = `<i class="fas fa-arrows"></i> ${val} inch = ${cm} cm`;
      }
    }

    document.getElementById('toInchBtn').addEventListener('click', () => convertLength('cmToInch'));
    document.getElementById('toCmBtn').addEventListener('click', () => convertLength('inchToCm'));

    // initial conversion (cm->inch)
    setTimeout(() => convertLength('cmToInch'), 10);
    lengthInput.addEventListener('input', () => convertLength('cmToInch'));

  })();
</script>

</body>
</html>
